window.harnessChunks["rows-8599da90e8679eee.js"]=["<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-16T23:24:44+03:00\"><th scope=\"row\"><a href=\"https://github.com/microsoft/autogen\" target=\"_blank\" rel=\"noopener\">Microsoft AutoGen AgentChat</a><small>2023</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/microsoft/autogen/tree/027ecf0a379bcc1d09956d46d12d44a3ad9cee14\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 027ecf0a379bcc1d09956d46d12d44a3ad9cee14\">027ecf0 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: stateful agents choose tools/actions and incorporate returned results.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: team selection plus Magentic-One&#39;s explicit loop/stall detection and controlled transfer of the next action right suppress uncontrolled repetition/interference among multiple S1 participants. This is more than mere delegation.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: MagenticOneOrchestrator owns a whole-team current facts/plan/progress ledger and has authority to assess progress, choose commitments, reset participants and regenerate the plan when the team stalls. Code-execution approval constrains an operational executor action rather than independently owning this whole-team current-control loop, so no separate (P) mode is published.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: the progress ledger is part of the same operational S3 regulator that directs the team. It is not a distinct complementary audit channel with separate reviewing independence.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: replanning after current-task stalls is inside-now adaptation. No distinct external/prospective intelligence function shaping future organizational posture is established.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: participant set, instructions, termination rules and ultimate authority remain application/parent-owned.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9ee1ea7472777767928c8b2ab035e0948a0467e9/assessments/autogen-agentchat.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9ee1ea7472777767928c8b2ab035e0948a0467e9\">9ee1ea7 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-20T21:45:19+03:00\"><th scope=\"row\"><a href=\"https://github.com/Technion-Kishony-lab/data-to-paper\" target=\"_blank\" rel=\"noopener\">data-to-paper</a><small>2023</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/Technion-Kishony-lab/data-to-paper/tree/81df14c4b9600466e645c3b2b336cc54daa3df3a\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 81df14c4b9600466e645c3b2b336cc54daa3df3a\">81df14c &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously perform the environment-facing scientific work needed to transform project data and research state into executable analyses and research artifacts. - Disturbance / variety regulated: heterogeneous datasets, generated-code errors, unexpected outputs/files, statistical-analysis requirements, intermediate product state and manuscript construction requirements. - Decisive decision or feedback right: choose and revise analysis/code/content actions in response to current project products, execution results and validation/reviewer feedback. - Decision owner: the active first-party performer/code-writing agents in the hypothesis-testing workflow. - Supporting / enforcement mechanisms: stage runner, CodeRunner, debugger conversers, code extract/check logic, output requirements, product store, data chaining and configured iteration bounds. - Closure path: current scientific products/data -&gt; agent proposes code/content action -&gt; first-party runner executes/materializes it -&gt; output/error/product state returns -&gt; agent revises or advances. - Boundary reachability: these paths are the shipped hypothesis-testing research workflow invoked by the installable application/CLI, not benchmark-only examples. - Why this is / is not agent-owned: runtime and guardrails execute/check code, but the context-sensitive analysis/content choice and revision remain model-agent decisions. - Evidence: README.md, stepsrunner.py, requestcode.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no material first-party S2 coordination path is established at the reviewed recursion. - Disturbance / variety regulated: the workflow contains multiple performer/reviewer roles and research stages, but no concrete interference, conflict or oscillation among distinct S1 units is identified and attenuated by a dedicated coordination relation. - Decisive decision or feedback right: none established for S2. - Decision owner: none established for S2. - Supporting / enforcement mechanisms: typed stage transitions, product passing, paired conversations, deterministic sequencing and rewind/retry utilities. - Closure path: these mechanisms sequence work and transmit review feedback; they do not close a cross-S1 interference-regulation loop. - Why this is / is not agent-owned: interacting agents and state transfer are real, but the reviewed paths are production/review dependencies rather than S2-specific conflict attenuation. - Evidence: stepsrunner.py, dualconverser.py. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no autonomous whole-system inside-and-now control function is established at the reviewed recursion. - Disturbance / variety regulated: stage completion, retries, rewinds, project parameters and review rounds constrain current work, but no first-party autonomous actor is shown holding a whole-project current view plus broad authority over shared resources/commitments/priorities. - Decisive decision or feedback right: stage flow and retry bounds are primarily encoded in deterministic runner logic and project parameters; local reviewers control product acceptance rather than organization-wide current control. - Decision owner: none established for S3. - Supporting / enforcement mechanisms: DataStepRunner/HypothesisTestingStepsRunner, stage enums, product readiness, retry/rewind helpers, project parameters and UI actions. - Closure path: configured stage/retry conditions alter control flow mechanically; no discretionary whole-system S3 owner is evidenced. - Why this is / is not agent-owned: model agents make local scientific/product decisions, while the broader workflow sequence is framework-defined. - Evidence: stepsrunner.py, README.md. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: provide a separate challenge channel that reviews scientific/code/writing products and returns concrete corrective feedback before those products are accepted. - Disturbance / variety regulated: plausible-but-wrong analysis outputs, code/result problems, weak hypotheses/plans, writing defects and other product claims that ordinary performer generation may miss. - Decisive decision or feedback right: independently approve a product or issue constructive concerns that force another performer revision cycle. - Decision owner: the separate reviewer LLM conversation in ReviewDialogDualConverserGPT and review-specific subclasses; in code paths, review agents inspect executed outputs/code products separately from the generating/debugging conversation. - Supporting / enforcement mechanisms: separate ConversationManager, review termination phrase, max review rounds, product extraction/checks, code-review prompts and rewind utilities. - Closure path: performer produces valid candidate -&gt; reviewer receives the candidate/background -&gt; reviewer approves or supplies concerns -&gt; concerns are appended to the performer conversation with explicit correction request -&gt; performer rewrites/revises -&gt; review repeats. - Boundary reachability: the review dialog base class is reused by goal, planning and manuscript-writing review steps in the shipped hypothesis-testing workflow; code review is also embedded in the standard code-product path. - Why this is / is not agent-owned: the reviewer is a separate agent conversation and owns the semantic approve/challenge judgment; deterministic loop code only routes/enforces that judgment. - Claim being audited: that a current scientific product/code result is adequate/correct enough to become accepted workflow state. - Ordinary reporting path: performer response plus normal generated/executed product state. - Complementary access path: separate reviewer conversation receives the product and relevant background/output context; code review can inspect created output contents. - Independence boundary: reviewer has its own conversation manager/role and does not share the performer&#39;s assistant role; review feedback is generated independently and then returned. - Who acts on findings: the original performer/code-writing agent revises the product in the next cycle. - Evidence: dualconverser.py, requestcode.py, stepsrunner.py. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A(P) - Function: use external literature/novelty evidence to develop or revise future research direction and return the selected direction into the current experimental plan, with both autonomous and Copilot parent-governed modes. - Disturbance / variety regulated: existing literature may make a candidate goal non-novel, external findings may change relevant hypotheses, and a human scientist may judge the proposed future direction inadequate. - Decisive decision or feedback right: in Autopilot, research/novelty agents judge literature-derived novelty and generate/refine the goal/hypothesis; in Copilot, human review can replace/supplement reviewer feedback and require revised research products. - Decision owner: autonomous research/reviewer agents in base mode; human scientist in the supported Copilot parent mode for the reviewed future-direction decision. - Supporting / enforcement mechanisms: literature-search agents, NoveltyAssessmentReview, ReGoalReviewGPT, stage return to GOAL, human-review application interactions, product storage and plan handoff. - Closure path: external literature -&gt; novelty/goal review -&gt; autonomous or parent judgment -&gt; if inadequate, workflow returns to goal generation/refinement -&gt; resulting goal/hypothesis/testing plan feeds data analysis and later research stages. - Boundary reachability: literature/novelty/goal refinement is part of the shipped hypothesis-testing runner, and README plus HumanReviewType/review interaction code expose Copilot human feedback through the same first-party workflow. - Why this is / is not agent-owned: the base mode closes without human direction through model-agent novelty/refinement decisions; the separately supported Copilot mode intentionally transfers the relevant review/judgment right to the human and returns that decision into workflow state. - External distinction: retrieved scientific literature and most-similar-paper evidence. - Future / prospective distinction: whether the current research goal/hypothesis is novel/appropriate enough to warrant future experimentation. - Adaptation option generated: revised research goal/hypothesis and downstream hypothesis-testing plan. - Path back into current capability / S3: failed novelty sets regoal and returns to ScientificStage.GOAL; accepted/revised goal then feeds planning, code analysis and manuscript stages. - Evidence: stepsrunner.py, dualconverser.py, README.md. - Basis: structural -\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party identity/ultimate-policy closure is established. - Disturbance / variety regulated: project parameters, research goals, human feedback and methodological guardrails constrain work, but no identity-level dispute is routed to an ultimate authority and returned as governing organizational policy. - Decisive decision or feedback right: none established for S5. - Decision owner: none established for S5. - Supporting / enforcement mechanisms: startup/project parameters, user research goal, coding guardrails, reviewer prompts and human-review UI. - Closure path: these controls constrain local research behavior directly; no identity/ultimate-policy issue -&gt; authoritative decision -&gt; returned policy loop is evidenced. - Why this is / is not agent-owned: neither autonomous agents nor the Copilot human are shown resolving an identity-level policy issue at this recursion. - Evidence: README.md, stepsrunner.py. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/c9da28372ac35ff5d8bc9a74679a6987a5d451df/assessments/data-to-paper.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit c9da28372ac35ff5d8bc9a74679a6987a5d451df\">c9da283 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"1\" data-assessment-at=\"2026-09-21T19:11:00+03:00\"><th scope=\"row\"><a href=\"https://github.com/zhayujie/CowAgent\" target=\"_blank\" rel=\"noopener\">CowAgent</a><small>2022</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-20\">2026-09-20</time></td><td class=\"review-ref\"><a href=\"https://github.com/zhayujie/CowAgent/tree/7c55a61e1bccb82c99d97a4a436f598c079f7c9d\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 7c55a61e1bccb82c99d97a4a436f598c079f7c9d\">7c55a61 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomously transform user/scheduled/delegated objectives into environment-facing tool/skill work and returned outcomes. - Disturbance / variety regulated: heterogeneous user objectives, model uncertainty, tool results/errors, files/shell/browser/service state, channel messages, and follow-up observations encountered during a trajectory. - Decisive decision or feedback right: choose the next reasoning/tool/skill action, incorporate returned observations, delegate bounded work when useful, or stop with a final response. - Decision owner: the running CowAgent Agent/model actor inside the first-party AgentStreamExecutor loop. - Supporting / enforcement mechanisms: ChatService, AgentBridge, provider adapters, prompt/workspace construction, tool registry, permissions, session persistence, scheduler integration and context controls. - Closure path: each tool result, delegated result or new model observation returns into the first-party executor context and can change the next autonomous action until completion. - Boundary reachability: the credited executor/bridge/tool path is the normal shipped Web/channel runtime and is instantiated directly by standard CowAgent operation at the pinned revision. - Why this is / is not agent-owned: deterministic code supplies transport, limits and execution, while the model actor owns the discretionary next-action choice on each loop iteration. - Evidence: pinned agent/chat/service.py and bridge/agentbridge.py; README.md corroborates the shipped planning/tool execution boundary. - Basis: structural and explicit. - Confidence: high. - Caveats: model/provider/tool availability, permissions and iteration limits constrain the Agent&#39;s operational discretion but do not replace its next-action judgment.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: attenuate a concrete interference between sibling operational Agents when concurrent delegations target the same persistent relay conversation. - Disturbance / variety regulated: concurrent handoffs to one source→target relay session would otherwise interleave turns in the target Agent&#39;s transcript and corrupt the shared conversational state used by later delegated work. - Decisive decision or feedback right: serialize admission to that target relay session so exactly one delegated turn occupies it at a time; timeout rather than permit an overlapping handoff when the lock cannot be acquired within policy. - Decision owner: constructor-owned at the assessed boundary. The first-party S2-specific serialization primitive is complete and operational, but the conflict policy itself is deterministic/developer-selected rather than autonomously chosen by an Agent. - Supporting / enforcement mechanisms: per-relay relaylock, stable relay-session derivation, delegation roster/ACL, depth/cycle checks, timeout and synchronous result return. - Closure path: a source Agent&#39;s delegation blocks on the relay lock; after the prior target turn finishes and releases the lock, the next delegated target run executes against a non-interleaved transcript and its result returns to the waiting source Agent, changing that source&#39;s subsequent S1 behavior. - Boundary reachability: agentdelegate is a shipped team tool attached to normal team turns through AgentBridge; no downstream coordinator or test-only actor is required for the serialization path. - Why this is / is not agent-owned: Agents autonomously decide to delegate and select the teammate/task, but once two handoffs conflict the coordination choice is a fixed first-party lock policy. CowAgent therefore exposes a real S2-specific construction path without an autonomous owner of the conflict-regulation decision. - Evidence: pinned agent/tools/agentdelegate/agentdelegate.py and team-session support in bridge/agentbridge.py. - Basis: structural. - Confidence: high. - Caveats: other team features such as speaker selection, shared transcripts and ordinary handoff are not separately credited as S2 merely because they connect Agents. - Distinct S1 units: independently configured live CowAgent Agents with separate profiles/workspaces and first-party execution loops participating in one team conversation. - Inter-S1 disturbance: overlapping delegated turns to the same target relay session can interleave in the target transcript. - Attenuating coordination relation: the first-party per-relay lock queues competing handoffs and allows only one target turn at a time. - Feedback into subsequent S1 behaviour: the coordinated target result is returned synchronously to the delegating source Agent&#39;s tool loop; timeout/failure likewise returns a result that changes the source Agent&#39;s next decision. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the lock exists specifically because concurrent sibling handoffs would interfere by interleaving one operational transcript, and it changes admission/timing to suppress that identified disturbance before results feed back to the source Agent.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: regulate the currently configured CowAgent installation as a whole by changing which operational Agents are available, which models/capabilities they use, and which live channel instances/teams route work to them. - Disturbance / variety regulated: current mismatch between installed operational capacity and the operator&#39;s desired roster, agent availability, model/capability allocation, shared/own knowledge mode, default ownership and live channel/team bindings. - Decisive decision or feedback right: create/update/archive/delete an Agent, make an Agent default, enable/disable it, alter its model/skills/knowledge allocation, or rebind a running channel/team to a different Agent roster. - Decision owner: the authenticated self-hosted operator is the legitimate parent actor in this supported mode. - Supporting / enforcement mechanisms: AgentAdminService, roster revision checks, Web authentication, registry/router rebuilding, scheduler reconciliation, targeted live-runtime eviction and hot channel rebinding. - Closure path: the operator submits a first-party Web/API decision; CowAgent persists it, updates the live registry/router or channel binding, starts/stops the affected schedulers and evicts changed Agent instances so subsequent current work is executed under the returned control decision. - Boundary reachability: the authenticated Web console and its /api/agents administration paths are a standard shipped self-hosted operating surface documented as the unified configuration hub, not a development-only control plane. - Why this is / is not agent-owned: no standard first-party autonomous Agent is given installation-wide roster/model/capability/channel authority. The decisive current-control choice comes from the authenticated operator; runtime code only validates, persists and enforces it. - Evidence: pinned agent/admin.py, channel/web/api/agents.py, and bridge/agentbridge.py scheduler/runtime reconciliation. - Basis: explicit and structural. - Confidence: medium-high. - Caveats: this claim is limited to installation-level current capability/resource control. Per-task steering/cancel and permission enforcement alone would not establish S3, and the assessment does not treat every settings edit as an S3 decision. - Whole-system current view: AgentAdminService.snapshot() exposes the installation&#39;s full current Agent roster, default Agent and channel instances; the same authenticated surface operates over that roster rather than one worker-local state. - Current-control decision scope: availability of S1 units, current model/capability allocation, default Agent, channel/team routing and scheduler participation for the running installation.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: no material first-party complementary and sufficiently independent audit function was established at the declared installation boundary. - Disturbance / variety regulated: none established as an S3 witness; ordinary tool feedback, run/event recording and Self-Evolution review do not provide a materially independent route to operational reality for checking production claims. - Decisive decision or feedback right: no S3-specific independent audit judgment/feedback right is supplied. - Decision owner: not established. - Supporting / enforcement mechanisms: execution/tool events, conversation/run persistence, evolution records/backups, logs and operator inspection surfaces. - Closure path: no independent audit finding→corrective-current-control loop was established; recorded events and evolution changes serve their primary execution/adaptation purposes. - Why this is / is not agent-owned: there is no qualifying audit function whose decisive judgment could be assigned to an autonomous Agent. - Evidence: pinned chat/executor event path, conversation storage, Web/admin surfaces, and agent/evolution/ review path. - Basis: structural. - Confidence: high. - Caveats: a downstream deployment could add an independent verifier or external monitor, but that composed system would be outside this frozen first-party boundary.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:4\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S4 / adaptation: - State: A - Function: convert externally observed conversation patterns and capability failures into prospective adaptations of reusable future capability. - Disturbance / variety regulated: changing user preferences and recurring work patterns, skill defects discovered in real use, reusable workflows not yet encoded as capabilities, and unfinished work whose recurrence or omission would reduce future fit. - Decisive decision or feedback right: after an idle conversation, decide autonomously whether there is a clear durable signal and whether to patch an existing skill, create a new reusable skill, consolidate knowledge/memory, or take no adaptation action. - Decision owner: the isolated first-party Self-Evolution review Agent/model actor. - Supporting / enforcement mechanisms: idle trigger thresholds, restricted evolution toolset, guarded workspace paths, pre-change backup, snapshot diff/change detection, transactional rollback and evolution records. - Closure path: the review Agent senses conversation-derived external signals, selects and writes an adaptation, the executor commits only real guarded changes, and later normal Agent runs load/use the revised skill/knowledge/persona state; if no clear signal exists it explicitly leaves capability unchanged. - Boundary reachability: Self-Evolution is started by normal AgentBridge initialization, its configuration class defaults enabled, and the standard pinned config-template.json ships selfevolutionenabled: true; the decision actor is therefore reachable in the supported distribution without borrowing a dogfood or contributor agent. - Why this is / is not agent-owned: trigger timing, backups and write guards are deterministic support, but the model review Agent owns the discretionary judgment of whether a past external interaction predicts future reusable need and which permitted adaptation to make. - Evidence: pinned agent/evolution/config.py, trigger.py, executor.py, prompts.py, bridge/agentbridge.py, config-template.json and docs/memory/self-evolution.mdx. - Basis: explicit and structural. - Confidence: high. - Caveats: simple memory consolidation alone is not the credited S4 witness. The positive mapping relies on the separately evidenced prospective skill-adaptation path: detecting a workflow likely to be wanted again or a skill defect exposed in use, autonomously generating an adaptation, and returning that change into later capability. - External distinction: the review consumes user conversation and actual skill/task experience from the environment, including repeated preferences, failures and emergent workflows. - Future / prospective distinction: the evolution prompt explicitly asks whether a workflow is reusable and likely to be wanted again, and documentation defines the goal as creating/fixing skills so they can be reused next time and future conversations improve. - Adaptation option generated: patch a defective skill, encode an emergent workflow as a new reusable skill, consolidate durable knowledge/memory, complete suitable unfinished work, or deliberately make no change. - Path back into current capability / S3: committed workspace/skill/knowledge changes are the same first-party artifacts read by subsequent normal Agent operation; operator rollback remains a separate parent intervention path rather than the owner of the autonomous adaptation judgment.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S5 / identity: - State: A(P) - Function: govern the Agent&#39;s durable identity/personality and highest-level workspace behavioral principles through first-party identity files that are loaded into subsequent system prompts. - Disturbance / variety regulated: drift between the Agent&#39;s durable identity/behavioral principles and explicit repeated signals about what the assistant should be, plus explicit operator decisions to redefine those identity/policy artifacts. - Decisive decision or feedback right: in the autonomous mode, decide whether an explicit repeated identity/personality/style signal is strong enough to justify a bounded AGENT.md identity revision; in the parent mode, authoritatively edit AGENT.md/RULE.md through the authenticated core-file administration surface. - Decision owner: base mode — the isolated Self-Evolution review Agent for the deliberately narrow autonomous identity-evolution decision; parent mode — the authenticated self-hosted operator as ultimate authority over the installation&#39;s core identity/policy files. - Supporting / enforcement mechanisms: evolution signal criteria and guarded writes/backups; AgentAdminService core-file revision checks and atomic writes; authenticated Web endpoint; prompt/workspace loader; targeted runtime eviction after operator edits. - Closure path: autonomous mode: repeated identity-level external signal → review-Agent identity judgment → guarded AGENT.md edit → subsequent runtime loads the changed persona. Parent mode: authenticated operator reads/edits a core identity/policy file → atomic persistence and cached-Agent eviction → subsequent Agent instance reloads that file into its system prompt. - Boundary reachability: both modes are shipped supported runtime paths: default-enabled Self-Evolution may edit AGENT.md under its standard guard, while the authenticated Web Agents API exposes core-file read/write and immediately evicts the changed runtime. - Why this is / is not agent-owned: the base identity change is not a static prompt or automatic parser; the review Agent must judge whether a rare explicit repeated signal warrants changing its own identity artifact. The separate operator mode retains parent authority to set or override the same identity/policy surface, hence A(P) rather than plain A. - Evidence: pinned agent/evolution/prompts.py, executor.py, agent/prompt/workspace.py, agent/prompt/builder.py, agent/admin.py and channel/web/api/agents.py. - Basis: explicit and structural. - Confidence: medium-high. - Caveats: ordinary permission settings, tool approvals, memory/preferences and per-task steering are not credited as S5. The autonomous claim is narrowly limited to the explicit first-party AGENT.md identity-evolution path; operator edits establish the separate parent mode. - Identity / ultimate-policy issue: AGENT.md is explicitly defined by the shipped templates as the Agent&#39;s identity/personality and is loaded with RULE.md into the system-prompt context; this is materially different from ordinary task or tool policy. - Ultimate authority in each claimed mode: base (A) — Self-Evolution Agent decides whether the standard rare-signal criterion warrants a durable identity edit; parent (P) — authenticated operator directly owns the authoritative core-file edit and may override/undo Agent evolution. - Return-to-operation path: both modes persist the core file used by prompt construction; operator writes additionally evict the cached runtime, and later Agent initialization reloads the changed identity/policy context.\">A(P)</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/a00011ae5e8e9ee62aa713d51f283559f12102d4/assessments/cowagent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit a00011ae5e8e9ee62aa713d51f283559f12102d4\">a00011a &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"3\" data-a=\"3\" data-c=\"0\" data-assessment-at=\"2026-09-16T23:24:44+03:00\"><th scope=\"row\"><a href=\"https://github.com/agno-agi/agno\" target=\"_blank\" rel=\"noopener\">Agno</a><small>2022</small></th><td class=\"counts-cell\" data-sort-value=\"3\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>3</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-09-15\">2026-09-15</time></td><td class=\"review-ref\"><a href=\"https://github.com/agno-agi/agno/tree/44219f8532e2fe6ce936850455f4b9a2567e4194\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 44219f8532e2fe6ce936850455f4b9a2567e4194\">44219f8 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: member agents autonomously execute bounded model/tool work and return results.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: TeamMode.tasks provides an out-of-box agent-owned mutual-adjustment loop over a shared task board. The leader assigns ownership, prevents duplicate tasks, encodes dependencies, observes member outcomes and can retry/reassign/change the plan; dependency state prevents conflicting/premature execution. This goes beyond one-shot delegation.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: the same leader has a current whole-team view of tasks, assignees, dependency/blocked state, results and failures, plus authority to create/reprioritize through dependencies, assign/reassign members, execute work, update status and decide overall completion. That is a concrete agent-owned current-control loop over shared operational commitments. Human-in-the-loop paths pause member/tool execution and return the result to the team; they do not independently take ownership of the team-level assignment/plan/completion right, so no separate (P) mode is published.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: Agno lets applications compose reviewer/critic members, but the standard team runtime does not supply a distinct sufficiently independent audit channel with alternative operational access and required corrective closure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: memory, knowledge, reasoning and learning capabilities can improve team operation but do not by themselves instantiate a distinct external-and-prospective intelligence function coupled against S3.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: team role, instructions, permissions, approvals and identity are application/parent configured. The tasks leader regulates execution but is not given ultimate agent-owned policy/identity authority or an S3–S4 closure role.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/9ee1ea7472777767928c8b2ab035e0948a0467e9/assessments/agno.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 9ee1ea7472777767928c8b2ab035e0948a0467e9\">9ee1ea7 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-08T15:12:56+03:00\"><th scope=\"row\"><a href=\"https://github.com/chenofchina/onion-harness\" target=\"_blank\" rel=\"noopener\">Onion Harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-08\">2026-11-08</time></td><td class=\"review-ref\"><a href=\"https://github.com/chenofchina/onion-harness/tree/dc2be116eddad9c45018d0d8590fa6cc96387bfe\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision dc2be116eddad9c45018d0d8590fa6cc96387bfe\">dc2be11 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: first-party hosted model agents interpret user tasks and perform tool or deliberative work in local environments. - Disturbance / variety regulated: changing user goals, tool results, file/task conditions and differing model-seat arguments. - Decisive decision or feedback right: model-backed agent chooses next task-level action/tool call or substantive seat reply/rebuttal from prompt and feedback. - Decision owner: model-backed agent actor in normal mode; individual seat agents in Roundtable. The deterministic Onion application and external engine transport the choice. - Supporting / enforcement mechanisms: EngineLoop, provider adapters, executor registry, sandbox, Plan/Standard/Strict mode, approvals, memory, task events and configured ceilings. - Closure path: agent-selected call reaches an Onion executor, tool result returns to engine context for further agent choice; Roundtable seat replies enter the shared transcript and later rounds/final consensus. - Boundary reachability: OnionRuntime.runtask wires live tools/options into EngineLoop.run; the API constructs and starts Roundtable in a supported application path, rather than only in tests. - Why this is / is not agent-owned: model-dependent action and substantive reasoning disappear with the agent actor, while retaining Onion&#39;s deterministic mechanics; the latter do not independently choose the goal&#39;s actions. - Evidence: runtime loop, tool creation and feedback, Roundtable turn/feedback. - Basis: structural. - Confidence: high for shipped model-backed action/seat loops; no claim of successful paid-provider E2E execution in this review. - Caveats: the internal loongagent dependency is not separately assessed; local app uses its installed engine and a configured model rather than a first-party foundation model.\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: Roundtable reduces blocking disagreements among independent model-seat contributions to produce a coherent joint deliberative outcome or a bounded explicit divergence. - Disturbance / variety regulated: incompatible seat stances and directed rebuttals can prevent the meeting from converging. - Decisive decision or feedback right: the model-backed host chooses the first seat per round after reading the evolving transcript and outstanding disagreement; each seat can revise/rebut from shared feedback. - Decision owner: host model agent for the discretionary next-speaker selection; other seat agents own their subsequent replies. Deterministic consensus/budget computation does not inherit that discretion. - Supporting / enforcement mechanisms: shared transcript, validated seat IDs, fixed tail speaking order, agreement/rejection parsing, round/call/token ceilings and human breaker. - Closure path: conflict appears as rejected stances/rebuttals; the host reads the transcript and selects the next first speaker, seats read preceding positions on later turns; consensus or the recorded divergences determines whether to stop, continue or involve the human. - Boundary reachability: the user-facing Roundtable API creates an actual RoundtableOrchestrator, while speakingorder makes a live host model call on its first-party normal execution path. - Why this is / is not agent-owned: removal of host deliberation leaves only deterministic rotation, not the dispute-aware speaker choice; mechanical ordering and consensus calculation remain supporting machinery. The host&#39;s returned focus field is not presently forwarded as a direct seat instruction, so the positive witness is bounded to first-speaker selection plus visible transcript/replies, not a stronger agenda-control claim. - Distinct S1 units: 2–6 model-backed seats with separate replies and optional rebuttal targets. - Inter-S1 disturbance: concrete disagreeing stances/rebuttals about the shared topic, which block consensus. - Attenuating coordination relation: host selection uses the transcript and prompts priority to whoever can address the open disagreement; subsequent seats see the accumulated positions. - Feedback into subsequent S1 behaviour: next round&#39;s host prompt and seat prompts include preceding contributions, and the consensus result stops/continues the meeting. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: a real conflict representation (rejections/targeted rebuttals) is tied to disagreement-aware host choice and a next-round response path; generic message passing alone is not the credited function. - Evidence: host and seat prompts, host choice, rebuttal and consensus path, verdict implementation, rebuttal/breaker tests. - Basis: structural. - Confidence: medium; source proves a dispute-specific feedback design, not observed convergence improvement under live provider conditions. - Caveats: this is S2 in supported Roundtable mode, not in an ordinary single-agent session. The host model&#39;s optional close and focus JSON fields are not the decisive mechanical closure of a round.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: parent/operator supervision of the current Roundtable&#39;s resource composition and commitments across its model-seat cells. - Disturbance / variety regulated: debate stalls, insufficient specialist coverage, divergent statements or unsatisfactory current answer distribution across seats. - Decisive decision or feedback right: the human operator chooses the meeting roster/model constraints at creation and can add a new seat, address one or all seats, and return a new directive while the meeting is underway or after the breaker. - Decision owner: the local human/operator at the application/meeting parent boundary; model host selection alone does not establish agent-owned whole-system S3. - Supporting / enforcement mechanisms: meeting status/roster/minutes, API mediation, capped seat count, inbox, event persistence, model-cost and breaker display. - Closure path: a user-added seat joins the next meeting round; a targeted message enters that seat&#39;s inbox and is delivered at its next speaking turn; post-meeting human input reopens a bounded follow-up without silently clearing prior consensus. - Boundary reachability: the shipped Roundtable UI/API connects operator messages and seat addition to the same live orchestrator and its subsequent rounds. - Why this is / is not agent-owned: the model host cannot decide to create extra provider seats or authoritatively change the operator&#39;s live constraints; these are returned human current-control decisions. Generic cancel and destructive-command approval are not separately counted as whole-system S3. - Whole-system current view: Roundtable&#39;s member roster, statements, per-seat usage, divergences and minutes are available to the user across its current operational seats. - Current-control decision scope: parent choices over team composition, targeted priorities and intervention within the bounded meeting; not an inferred global allocator across independent Onion tasks. - Evidence: Roundtable UI contract, human messages/follow-up, live seat addition, inbox return. - Basis: structural. - Confidence: medium; the positive parent claim is bounded to the current Roundtable, not whole installation-wide budgeting. - Caveats: the operator can be human and does not need to be modeled as an AI agent; no autonomous S3 resource/commitment discretion is established merely from timeouts/host ordering.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: a separate audit would have to compare ordinary operational success/claims against independent underlying reality and return findings to current control. - Disturbance / variety regulated: false reported completion, unsound execution, unobserved side effects or unverifiable model claims. - Decisive decision or feedback right: not established as a distinct first-party complementary operational audit right in the reviewed modes. - Decision owner: none evidenced for such a distinct audit; the optional safety-review model judges proposed code before execution, and the user can approve a flagged request, but neither audits a claimed completed operational outcome through another access path. - Supporting / enforcement mechanisms: code-only safety filter, Plan mode refusal, user confirmation, diff view, tests and logs. - Closure path: no first-party complementary direct-reality audit finding is wired to corrective control as a separate function. Safety-review verdicts affect the ordinary executor&#39;s pre-execution gate only. - Why this is / is not agent-owned: an isolated reviewer model is not an S3 owner without a complementary audit of operating reality; authors explicitly call it a filter, not final authority. - Evidence: review-gate invocation, code-only review, README warning. - Basis: structural. - Confidence: medium-high within the shipped runtime/reviewer/GUI paths inspected. - Caveats: no universal claim about unexamined third-party plugins or a user&#39;s own independent verification procedure.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S4 / adaptation: - State: P - Function: parent-governed prospective adaptation of the agent&#39;s future available model/tool/skill capabilities in response to demands from the external user/work environment. - Disturbance / variety regulated: new tool/provider/skill needs beyond the currently enabled local repertoire. - Decisive decision or feedback right: the working agent can formulate a reasoned future-capability change proposal, but only the legitimate local human/operator decides whether it changes the installed repertoire. - Decision owner: human parent for adoption of the future capability; no automatic agent-owned S4 closure is claimed. - Supporting / enforcement mechanisms: MetaTools proposal API, dry-run ledger diff, capability validation and versioning, MCP tool materialization and hot reload. - Closure path: user-supplied/newly encountered capability need reaches the agent prompt; agent may propose a new executor/provider/skill/MCP tool; parent applies the proposal; the next runtime constructs its tools/prompt from the revised state or hot-loaded MCP registry. - Boundary reachability: meta tools are added to the normal agent&#39;s live tool registry and afterledgerchange updates the shipped runtime, including persisted tool availability; this is not merely a developer roadmap or test fixture. - Why this is / is not agent-owned: only the parent approval changes capability. Counterfactually removing the parent leaves proposals un-applied and does not close adaptation; this is not S4=A. - External distinction: changing user tasks and available model/tool services create a capability gap that can be expressed through the tool&#39;s mandatory reason and proposal content; no autonomous external scanning is claimed. - Future / prospective distinction: requested changes alter tools/providers/skills for subsequent actions or sessions, not merely the immediate task answer. - Adaptation option generated: agent-proposed registration of an MCP tool, model-provider preset, executor or skill. - Path back into current capability / S3: approved ledger state is re-read by OnionRuntime / refreshed MCP tools and becomes an available action for subsequent S1 execution. - Evidence: default operating prompt, meta tool proposals, human apply/reload. - Basis: structural for shipped proposal/return; inferred for the external-demand-to-adaptation interpretation. - Confidence: medium-low. This is a supported parent-closed capability adaptation mode, not evidence of autonomous environmental forecasting or systematic S4 strategy. - Caveats: a generic user-chosen plugin is not S4 by itself; this positive claim is limited to the model-originated, reasoned future capability proposal and actual parent return path. No source trace establishes recurring environmental surveillance or measured adaptation effectiveness.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S5 / identity: - State: P - Function: parent-governed ultimate change to the agent&#39;s core identity and operating rules, rather than an ordinary task/tool approval. - Disturbance / variety regulated: tension between the current core behavior/policy and a desired enduring operating identity for future sessions. - Decisive decision or feedback right: human operator authoritatively accepts/rejects a model- or user-originated update to the persistent core system-prompt segment. - Decision owner: legitimate local human operator of the self-hosted agent, not the proposing agent or deterministic ledger. - Supporting / enforcement mechanisms: onionupdatesystemprompt, ChangeLedger validation/diff/version history, API confirmation and ordered system-channel prompt assembly. - Closure path: core operating-rule proposal reaches confirmation UI; operator calls apply/reject; accepted segment is persisted; composesystemprompt and OnionRuntime.composesystemprompt inject it into future model calls. - Boundary reachability: normal agent tool registry contains the prompt-update meta tool, and user-facing API applies proposals to live state read on every later task. No adjacent maintainer CI or unshipped governance actor is needed. - Why this is / is not agent-owned: model can suggest but cannot activate its own enduring identity/policy change. No separate autonomous S5 ultimate-authority mode is established. - Identity / ultimate-policy issue: the core segment begins with You are Onion and durable operating rules; changing that segment changes the identity-level instructions inherited by future tasks, distinguishable from approval of a particular shell command. - Ultimate authority in each claimed mode: only human parent mode positively established; autonomous policy proposal is not decisive authority. - Return-to-operation path: ledger apply persists the approved segment; the runtime composes the system channel from that state on the next run. - Evidence: core identity and policy, prompt-change proposal, parent application, runtime system-channel return. - Basis: structural. - Confidence: medium-high for the shipped parent closure; the grade does not imply the default agent authors its own constitutional rules. - Caveats: a generic per-tool confirmation is not counted as S5. This applies only when the human-authorized change affects the durable identity/core policy segment.\">P</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/2d4f179b0c40a972a750d2e91fbef975709c36d2/assessments/on/onion-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 2d4f179b0c40a972a750d2e91fbef975709c36d2\">2d4f179 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-05T21:55:57+03:00\"><th scope=\"row\"><a href=\"https://github.com/bondie/agent-harness\" target=\"_blank\" rel=\"noopener\">Agent Harness (ticket team)</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/bondie/agent-harness/tree/6c011629ecf3f0cb2cfd72084502e58a31ad3206\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 6c011629ecf3f0cb2cfd72084502e58a31ad3206\">6c01162 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Model-directed analysis, effort estimation and approved ticket-specific code changes in a target project. - Disturbance / variety regulated: Variable tracker requirements, codebase structure, acceptance criteria, failing tests, reference-ticket evidence and QA findings. - Decisive decision or feedback right: The analyst/estimator interpret ticket content and choose analysis/forecast; the implementer chooses substantive code edits and next local repair from test or review feedback within the approved task. - Decision owner: Instantiated Claude Code subagent models as operational actors, explicitly invoked by the installed ticket skill; human owns the scope gate, not code-level reasoning. - Supporting / enforcement mechanisms: Task-specific agent instructions, project-test post-edit hook, configurable precedent MCP, approval gate and tracker-write guard. - Closure path: Ticket → analyst/estimator choices → human-approved implementation → model-selected edits → repository/test observations → corrections → QA result and handover. - Boundary reachability: /agent-harness:ticket is the advertised installed entry point and explicitly names the subagents; the implementer definition grants Read/Write/Edit/Bash and receives the project test hook when configured. - Why this is / is not agent-owned: Remove the task-operating models and the prompt/hook package cannot interpret tickets or produce discretionary code changes; the host executes the tool choices but does not replace the task-local reasoning right. - Evidence: ticket skill, implementer, test feedback. - Basis: structural first-party installed workflow. - Confidence: High for defined agent decision roles; medium for live host behavior not independently exercised. - Caveats: Requires a configured external Claude Code runtime, tracker and target project; offline estimator experiments are not equivalent to live plugin decisions.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No evidenced inter-operational-unit interference attenuation loop, distinct from sequential work handoff. - Disturbance / variety regulated: A ticket can produce analyst/estimator/implementer disagreement, but no peer S1 oscillation or simultaneous incompatible commitments are detected and damped by a separate coordinator. - Decisive decision or feedback right: The lead follows a prescribed sequence and human gate; it has no evidenced S2-specific adjustment right over independent peer operations. - Decision owner: Lead role for local routing and human for plan changes; no separately demonstrated S2 owner. - Supporting / enforcement mechanisms: Fixed role sequence, approval before implementation, bounded QA cycles and role write restrictions. - Closure path: Task outputs pass to the next role; no qualifying peer-conflict signal → coordinating choice → adjusted peer behavior loop is established. - Why this is / is not agent-owned: Delegating roles and handing a result forward is not by itself regulation of interaction-generated operational variety. - Evidence: installed skill steps. - Basis: bounded structural absence. - Confidence: Medium-high. - Caveats: Other multi-team integrations are outside this ticket-team boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No demonstrated discretionary whole-system present-control allocation or operational-portfolio commitment loop. - Disturbance / variety regulated: Wrong estimates, implementation failures, failed tests and review findings are local task matters, not a cross-unit resource/commitment picture. - Decisive decision or feedback right: Human approves scope and external writes; lead gates a prescribed ticket sequence. No agent legitimately revises whole-system operational allocations. - Decision owner: Human for plan and write approval, implementer for task-local edits, prescribed skill for sequencing. - Supporting / enforcement mechanisms: Human AskUserQuestion before implementation, two QA correction rounds, configurable test command, tracker MCP write guard. - Closure path: Gate → approved individual ticket → implementation/review/handover; no cross-unit performance consolidation and current-control reallocation return. - Why this is / is not agent-owned: The lead&#39;s management label and task handoffs do not establish S3 portfolio authority at this recursion. - Evidence: ticket skill, tracker guard. - Basis: bounded structural absence. - Confidence: Medium-high. - Caveats: The human manager of multiple unrelated tickets could implement an external S3 that this package does not define.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: Distinct independent read-only QA inspection of implementation assertions before human handover. - Disturbance / variety regulated: Implementer claims of task completion despite erroneous code, missed acceptance criteria, missing tests or regressions. - Decisive decision or feedback right: The reviewer chooses approve or changes requested and reports verified path:line defects plus checks and criterion status independently of the implementer&#39;s report. - Decision owner: Separate reviewer-qa Claude Code subagent; the lead receives its verdict and routes requested corrections to the implementer. - Supporting / enforcement mechanisms: Explicit review step, reviewer disallowedTools: Write, Edit, NotebookEdit, direct git diff/git status and code-context reading, independent test execution and up to two corrective rounds. - Closure path: Implementer reports completion → distinct reviewer checks working-tree artifacts and runs validation → issue-specific verdict → lead sends defects back to implementer → new implementation and re-review → human sees evidence/verdict. - Why this is / is not agent-owned: The reviewer&#39;s substantive assessment/verdict is agent judgment on direct source/test evidence; the skill-owned orchestration returns it to the lead and influences completion. This is separate from ordinary implementer self-tests or a deterministic linter. - Claim being audited: Completed changes meet the ticket analysis and every acceptance criterion without production defects. - Ordinary reporting path: Implementer summary of files, tests and criteria returned to the lead after edits. - Complementary access path: Reviewer independently reads the actual uncommitted diff, status and surrounding files and executes read-only tests/linters/static checks. - Independence boundary: Separate named model subagent without edit tools; cannot edit audited code or merely reuse implementer self-report. It remains subject to the same provider/host and its invocation depends on lead compliance with installed skill instructions. - Who acts on findings: Lead routes verified QA findings into an implementer rework round and withholds final handover until the bounded review process completes or escalates to the human. - Boundary reachability: The installed primary /ticket skill explicitly calls reviewer-qa after implementer and reruns it on change requests; the reviewer definition prescribes primary-artifact inspection, a verdict and line-level findings. - Evidence: independent reviewer, review and correction steps, implementer report path. - Basis: explicit + structural first-party audit path. - Confidence: High for wired separation and corrective instructions, medium for compliance in unobserved live sessions. - Caveats: Prompt-level reviewer separation, not a cryptographically isolated verifier or automatic no-bypass acceptance gate. Claims of tests passing do not replace actual project test command provisioning.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No autonomous prospective adaptation of the ticket-team&#39;s organizational capabilities. - Disturbance / variety regulated: Historical ticket variability and changing complexity are used for current-task forecasting, not future operating-model change. - Decisive decision or feedback right: Estimator forecasts current ticket hours from precedents; no owned decision to revise future team tools, policy, capacity or capability. - Decision owner: Estimator for this task&#39;s prediction, user/developer for future plugin design and installed configuration. - Supporting / enforcement mechanisms: Historical precedent MCP and estimate P25–P75, offline model-evaluation scripts, explicit approved approach. - Closure path: Past tickets → estimate for the current task → human plan decision; no environment futures → strategic adaptation decision → operating-organization feedback. - Why this is / is not agent-owned: Reference-class forecasting is anticipatory about this ticket&#39;s effort, but does not itself establish S4 future-environment/capability adaptation. - Evidence: estimation step, estimator role. - Basis: bounded structural absence. - Confidence: High. - Caveats: External team planning informed by ticket forecasts could be a separate S4 outside this plugin.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No evidenced first-party ultimate-purpose, organizational identity or constitutional arbitration loop. - Disturbance / variety regulated: Risky code changes, tracker writes, plan deviations and unapproved commits are governed at an operational authorization level. - Decisive decision or feedback right: Human may approve implementation and individual write actions; no actor resolves a dispute about the team&#39;s enduring ultimate policy or identity. - Decision owner: Human requester for plan and action consent, installed rules/hooks for routine constraints; no packaged S5 owner. - Supporting / enforcement mechanisms: Explicit AskUserQuestion plan gate, no commit/push without human consent, subagent tracker-write denial hook. - Closure path: Proposed action → approval or denial → execute/stop; no identity/purpose dispute → legitimate policy-authority judgment → enduring organizational policy revision. - Why this is / is not agent-owned: Read-only write restrictions and per-action consent protect execution boundaries, not an S5 policy identity feedback loop. - Evidence: human gates, tracker guard. - Basis: bounded structural absence. - Confidence: High. - Caveats: Host global instructions and organizational identity policies reside outside this plugin.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/1ec53be3a1853bb4d51e279e16f4b959fe32b354/assessments/ag/agent-harness-ticket-team.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 1ec53be3a1853bb4d51e279e16f4b959fe32b354\">1ec53be &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"2\" data-assessment-at=\"2026-11-05T22:18:42+03:00\"><th scope=\"row\"><a href=\"https://github.com/berkesecicii/free-multi-agent-ai-council\" target=\"_blank\" rel=\"noopener\">JARVIS AI Council</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>2</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/berkesecicii/free-multi-agent-ai-council/tree/20a93de357da82c39255932da71dfb12aeea2f49\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 20a93de357da82c39255932da71dfb12aeea2f49\">20a93de &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: attached specialist agents independently execute coding, web-research, reading or review tasks and return task results and observations. - Disturbance / variety regulated: codebase state, provider tool results, user questions, web evidence and unexpected errors within each assigned specialist responsibility. - Decisive decision or feedback right: role model decides its research or code steps, tool requests and content after observing context/tool outputs; host controls access approval and routing. - Decision owner: selected model-backed specialist (VISION/Claude CLI, FRIDAY/Codex, EDITH/Gemini or other installed supported agent), not the deterministic Python routing rules. - Supporting / enforcement mechanisms: CLIs/adapters, project-command/patch/search, browser/desktop bridge, role-scoped chat context, saved task/output state and human permissions. - Closure path: user/JARVIS assigns task → first-party launcher reaches signed-in provider agent and approved tools → model consumes tool observations and delivers artifact/findings → host records output → later team stage or user consumes it. - Boundary reachability: providers are explicitly wired by first-party adapters and runtime launch; team runner selects their actual connector and creates a bounded child chat/task rather than only naming hypothetical specialists. - Why this is / is not agent-owned: provider-backed agents choose task-specific actions after observations, while local approval prompts and quotas do not themselves create agent discretion. - Evidence: shipped connectors and task semantics; task launch; live provider launching. - Basis: source-reachable supported model execution modes. - Confidence: medium-high for structure; external paid/subscription models not exercised. - Caveats: the first-party host cannot prove the quality of any third-party proprietary model&#39;s internal reasoning.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: first-party grouping and connector-busy guards attenuate incompatible overlapping work across specialist runs while returning completed producer context to a later specialist. - Disturbance / variety regulated: simultaneous role workers attempting the same constrained provider connector, or a dependent role acting before a producer output exists. - Decisive decision or feedback right: human/model step plans indicate dependencies or independent stages; host accepts at most two same-group jobs and refuses two concurrent uses of a connector; it defers dependent stages until the current group&#39;s work is collected. - Decision owner: static coordinator constructor and plan authors, not an agent capable of negotiating runtime contention or autonomously repairing a conflicted schedule. - Supporting / enforcement mechanisms: modeljobs provider-busy check, threading.Lock, same-connector rejection, parallel grouping, grouping barriers, bounded prior-stage packet, and failure/cancellation statuses. - Closure path: candidate parallel group is tested for connector conflict → only nonconflicting roles launch; the next group waits for current completion → collected result is returned as bounded context to subsequent role; if provider already busy, the team exits with explicit error instead of colliding. - Boundary reachability: teamrunner executes these checks directly before invoking first-party configured model adapters, and persists the workflow state visible to the user. - Why this is / is not agent-owned: interference attenuation is specific to distinct S1 agents sharing provider capacity and result dependencies; its selection policy is configured/deterministic, requiring further autonomous composition for S2=A. - Distinct S1 units: enabled EDITH research, VISION coding and FRIDAY review/development workers operating in the same team request. - Inter-S1 disturbance: overlapping role calls compete for shared provider capacity; a consumer role can act on an incomplete producer result. - Attenuating coordination relation: connector-distinct parallel group admission and completed-group barrier with packet return. - Feedback into subsequent S1 behaviour: conflict prevents launch and surfaces team error; completion unlocks subsequent stage and provides its result, so downstream work waits for producer evidence. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the witness is runtime prevention of a specific conflicting simultaneous provider use plus an explicit inter-role completion barrier, not the fact that prompts mention other agents. - Evidence: group building, connector checks and barrier; shared runtime job and quota guards. - Basis: first-party structural constructor path. - Confidence: medium. - Caveats: no agent-level merge conflict resolution or general distributed work scheduling is claimed; configured write permissions/isolated chats prevent some interactions without solving arbitrary semantic conflicts.\">C</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A(P) - Function: JARVIS assigns present team work to available specialists and constrains who executes next; in a separate supervised mode the human approves and starts a proposed multi-role plan. - Disturbance / variety regulated: mismatch between request and expertise, specialist availability/quota, excessive handoff depth and pending current workload. - Decisive decision or feedback right: in automatic chat mode the JARVIS model chooses to hand an actionable brief to another specialist, and host executes it within a two-handoff current chain; in explicit plan mode the operator decides whether the proposed role/effort/step commitments begin. - Decision owner: autonomous JARVIS coordinator model in the active auto-handoff configuration; legitimate Mac user/operator in the first-party reviewed-plan and direct-call configurations. - Supporting / enforcement mechanisms: role/connector availability and quota scans, model-authored HANDOFF parser, fithandoff corrections, hop/visited limits, team-plan and team-start, task/role progress and user-visible review card. - Closure path: base A: coordinator sees current request and available agents → selects next specialist/brief → host validates target, quota and hop bound → launches next model into the same team turn → completed work returns for coordinator synthesis. parent P: operator inspects the proposed team steps/roles → confirms start or selects agents directly → startteam executes selected commitments, returns results and gives operator stop/rework control. - Boundary reachability: auto handoff is a shipped default (autohandoff true), splithandoff and continuation call the actual model launch; the explicit reviewed plan path is offered by first-party team-plan/team-start actions and takes effect on real role runs. - Why this is / is not agent-owned: the agent can select the next current work commitment in the autonomous configured mode, while the operator has a genuinely distinct authorization path in the explicit-team mode. Deterministic caps merely bound both decisions. - Whole-system current view: the coordinator is briefed on callable team roles, their available connector/quota, the current shared chat and prior outputs; the human sees the complete team plan and current task/agent statuses in the app. - Current-control decision scope: current division of requested work among available team members, next assignment and effort, task-step commitment and interruption, not a company-wide financial/resource allocation claim.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: the shipped build→review team shape can provide a distinct model reviewer with a host-read snippet of actual changed files, separate from the implementer&#39;s prose report. - Disturbance / variety regulated: implementer reports success without grounding it in actual changed content or a second critique. - Decisive decision or feedback right: the plan or default FRIDAY review stage chooses the review function; a model may give a critique, but the host constructs the limited separate artifact-evidence packet, and no mandatory independent review acceptance gate is shipped. - Decision owner: constructed reviewer role with model critical judgment, invoked only in selected plans; human controls whether that optional stage is included and acted on. - Supporting / enforcement mechanisms: default FRIDAY review stage, separate child chat, previous-stage report packet and host ProjectBridge reads of approved changed-file excerpts. - Closure path: build specialist reports completion → host reads approved changed files from attached project and supplies excerpt alongside untrusted implementation report → distinct reviewer model critiques it → critique enters team results and final JARVIS presentation for the user / next current action. - Boundary reachability: startteam defines a real default FRIDAY reviewer after VISION; collect reads actual project paths and appends changed-file excerpts; the runner invokes the reviewer using its own connector, when enabled and configured. Not every dynamic or explicitly planned workflow elects review. - Why this is / is not agent-owned: the reviewer can judge content independently of the implementer&#39;s wording, but first-party code only constructs a bounded evidence packet and optional review; the reviewer does not automatically receive independent command execution in kind=review, so C is safer than a strong autonomous audit owner claim. - Claim being audited: code implementation and claimed changed-file result from the prior build stage. - Ordinary reporting path: model-authored stage output saved as a team task result, then passed to downstream roles. - Complementary access path: host ProjectBridge.path(...).readtext() for approved changed-file requests, packaged as Changed file excerpts to the next review stage. - Independence boundary: separate model agent with actual file excerpts not supplied by model prose; however excerpts are partial, only for recorded approved requests, and reviewer has no independent project tool rights in this review stage. - Who acts on findings: reviewer returns concrete failure/missing checks through team presentation to the user; no automatic veto or remediation is claimed. - Evidence: default review stage and excerpt construction; review role prompt; bounded project file access. - Basis: constructor-specific alternate evidence path; no guarantee of mandatory audit or outcome correctness. - Confidence: medium-low due optional stage and incomplete raw-artifact coverage. - Caveats: the default team plan omits unavailable roles and a model-generated plan may omit reviewer entirely; source snippets are the same worktree the implementer can change, not an isolated verifier workspace.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no first-party prospective environmental-sensing and capability-adaptation loop is closed at the installed team recursion. - Disturbance / variety regulated: future model/provider or external market changes are not transformed into a selected capability change by a shipped S4 decision process. - Decisive decision or feedback right: research specialist answers current tasks, while operator adjusts config; there is no routine future-option evaluation and adopted update path. - Decision owner: not supplied as a distinct adaptation authority. - Supporting / enforcement mechanisms: web search/research role, quotas, scheduled chat tasks, local role settings. - Closure path: task-local research may feed immediate work, but no exterior/future intelligence → alternative adaptation → approved capability revision loop is implemented. - Why this is / is not agent-owned: live web search and code building within a user brief are S1; a scheduled task or quota warning alone is not future-oriented organization adaptation. - Evidence: research and code routing; team planner; scheduler. - Basis: bounded structural negative. - Confidence: medium-high. - Caveats: human can ask a research→build sequence to improve the software, but that does not create a first-party enduring S4 procedure at this recursion.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no distinct ultimate-identity or policy-conflict decision transaction is closed through a legitimate internal parent authority and return path. - Disturbance / variety regulated: conflicting purpose/ultimate-policy demands are not represented as a governable S5 issue by the application. - Decisive decision or feedback right: user grants OS/project permissions and configures agents, but no built-in exceptional identity/policy adjudicator is invoked and returned. - Decision owner: external Mac user and OS entitlement authorities for ordinary permissions, not a first-party S5 loop. - Supporting / enforcement mechanisms: per-chat permission tiers, explicit risky-command approvals, prohibited app/action checks, selected role charters and user settings. - Closure path: user approves a requested tool action and it executes or is refused; that is local operation permission, not identity issue → final legitimate policy decision → governed future activity under a new policy resolution. - Why this is / is not agent-owned: hard safety rails and permission consent are fixed constraints for S1/S3 operation; they are not a viable organization&#39;s policy/identity decision right. - Evidence: README permission and safety rails; permission mode and work decision routing; project bridge. - Basis: bounded structural negative. - Confidence: medium-high. - Caveats: this denies a first-party closure path, not the existence of legitimate human or OS-level authority outside the assessed recursion.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/713e4282b33db357f31b0ce2894da2edac983ebd/assessments/ja/jarvis-ai-council.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 713e4282b33db357f31b0ce2894da2edac983ebd\">713e428 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-05T22:14:55+03:00\"><th scope=\"row\"><a href=\"https://github.com/Mohamed-jarboui/agent-runtime-harness\" target=\"_blank\" rel=\"noopener\">LoopSmith</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/Mohamed-jarboui/agent-runtime-harness/tree/0c6c7b170bc553be38909800ceb5132e52299e52\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 0c6c7b170bc553be38909800ceb5132e52299e52\">0c6c7b1 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Context-sensitive, model-directed workspace analysis and report construction through tools, handoffs and feedback. - Disturbance / variety regulated: Different project files, user objectives, tool responses, untrusted search results, coding/report findings, and reviewer feedback. - Decisive decision or feedback right: Choose file-inspection/search operations, tool arguments, model-generated findings/draft, and subsequent work from prior observations in configured live provider mode. - Decision owner: Model actor selected by AgentRuntime for the installed analyst role; first-party runtime owns constraints and tool execution, not the substantive task choice. - Supporting / enforcement mechanisms: Typed tool registry, provider resolution, JSON/tool validation, session/SQLite state, bounded loop, memory, permissions, approval and safe workspace tools. - Closure path: Goal → model agent receives system/context/tools → chosen tool/delegation or answer → stored tool result/error → updated model context → further choice or terminal workflow result. - Boundary reachability: CLI registers analyst roles and workflows; documented --provider option chooses configured live Anthropic/OpenAI-compatible provider. Default mock mode is explicitly labelled deterministic and not counted as autonomous S1 by itself. - Why this is / is not agent-owned: Live LLM selects meaningful investigation and writing actions; disabling the model leaves only scripted mock output and deterministic graph/tool enforcement. - Evidence: agent runtime loop, analyst role tools, CLI provider option. - Basis: explicit + structural first-party live-provider mode. - Confidence: High for model/tool decision wiring; actual model behavior/quality not exercised. - Caveats: Live credentials/model endpoint required; offline demo and evaluation suite cannot be substituted for live S1 evidence.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No specific operational-unit interference attenuation relation with its own feedback is established in the shipped workflows. - Disturbance / variety regulated: Specialist steps may depend on previous outputs; concurrent/conflicting independent S1 behavior and a correction loop for their interaction are not demonstrated. - Decisive decision or feedback right: Coordinator role can delegate research and hand off drafting, while graph engine follows author-defined routes; neither detects interaction-generated peer oscillation. - Decision owner: Model coordinator for task delegation; developer-authored graph/deterministic runtime for ordered transitions. - Supporting / enforcement mechanisms: Allow-listed agent.delegate and agent.handoff, bounded depth/count, workflow contexts and conditional transitions. - Closure path: Coordinator → specialist result → next step, or workflow state → fixed branch; no peer disturbance observation → S2-specific attenuation decision → revised peer commitments loop. - Why this is / is not agent-owned: Role routing, delegation and deterministic sequence are organizational plumbing, not proof of a distinct S2 regulatory function. - Evidence: meta-tools/handoffs, coordinator role, workflow. - Basis: bounded structural absence. - Confidence: Medium-high. - Caveats: A developer may compose multiple competing S1 teams with custom coordination, outside this reviewed installed mode.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No distinct discretionary whole-system present-control authority over a portfolio of operational commitments is shown. - Disturbance / variety regulated: Excessive tool calls, unsafe writes, retries, failed rubric checks and pending approvals; these are bounded by limits/gates within one task workflow. - Decisive decision or feedback right: Developer authors workflow transitions and caps; reviewer judges the report as a specific QA result; human approves individual writes, but no owner revises multiple S1 resource/priority commitments from a current whole-system view. - Decision owner: Operator/developer for envelope, runtime for deterministic steps and human for write permission; no separate cross-operational S3 manager in standard mode. - Supporting / enforcement mechanisms: Persistent workflow checkpoints, maxSteps/maxVisits, permission engine, approval state and structured reviewer verdict route. - Closure path: Draft → verification/review → revise/publish or human gate; this is local artifact acceptance, not whole-operating-system resource/commitment balancing. - Why this is / is not agent-owned: LoopSmith may be a reusable control-plane foundation, but it does not package a whole-portfolio S3 actor in the reviewed workflows; generic graph transitions alone do not count. - Evidence: workflow graph, workflow engine, permission defaults. - Basis: bounded structural absence. - Confidence: Medium-high. - Caveats: Higher-level orchestration/portfolio policy may be built by a customer from provided interfaces; no shipped specific owner/closure is established here.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: Evidence-facing independent report review, distinct from the report writer and fixed structural validators, with corrective return. - Disturbance / variety regulated: Generated reports can omit findings, cite nonexistent file lines or inaccurately describe workspace evidence while passing basic formatting checks. - Decisive decision or feedback right: Dedicated reviewer agent returns approved/needschanges, identified issues and explicit checkedEvidence judgments after spot-checking cited source with read-only tool. - Decision owner: Separate reviewer model role in shipped analyst workflow; the graph engine routes its verdict and the executor addresses findings. - Supporting / enforcement mechanisms: Reviewer tools:[&#39;workspace.read&#39;], permissions:{write:&#39;deny&#39;}, model instruction to inspect cited file/line, typed ReviewSchema and deterministic pre-review verifyReport structure checks. - Closure path: Researcher findings → executor draft → deterministic structure/coverage check → distinct reviewer reads cited source and renders verdict → failed verdict routes to draft revision with reviewer feedback → re-review or human escalation on visit cap. - Claim being audited: Draft technical improvement report accurately and completely presents workspace findings with valid citations and safe content. - Ordinary reporting path: Researcher model findings and executor model draft placed in workflow state; writer&#39;s own output is the completion claim. - Complementary access path: Reviewer has separate workspace.read access to actual workspace files and a required cited-line spot check, with structured checkedEvidence results; deterministic verifier supplies additional independently computed format checks. - Independence boundary: Named reviewer model role distinct from executor and researcher, its permissions deny file writes and it can directly inspect original code. It shares configured provider infrastructure and is not an external independent auditor; structural independence is at role/readonly-tool boundary. - Who acts on findings: Conditional workflow routes non-approval back to executor draft, inserting prior reviewer feedback; after visit limit, it asks a human whether to publish despite unresolved issues. - Boundary reachability: apps/cli/src/bootstrap.ts registers analystAgents/analystWorkflows; workspace-analyst is advertised in the README and has the review/return path first-party installed. - Why this is / is not agent-owned: The reviewer makes a discretionary evidence-verification judgment separate from writer&#39;s normal self-report; the code rule alone is not credited as S3. - Evidence: reviewer role/permissions, review and revision closure, installed bootstrap. - Basis: structural explicit first-party review closure. - Confidence: High for shipped definitions; moderate for live-model behavior because standard demo is deterministic. - Caveats: A single spot check is bounded evidence, not exhaustive verification. Structural checks and external provider performance cannot replace actual independent model review.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No closed future-environment sensing and strategic adaptation loop changing the harness&#39;s future organizational capabilities. - Disturbance / variety regulated: Historical memory and observations are used to answer the current task; provider fallback handles present availability rather than long-term adaptation. - Decisive decision or feedback right: Developer/operator changes prompts, agents, workflows and provider config; model planner selects current investigation steps only. - Decision owner: Developer/operator for prospective capability changes, task agents for current workflow. - Supporting / enforcement mechanisms: Persistent memory, context compaction, configurable workflow templates, model/provider registry, evaluation CLI. - Closure path: Stored observations → current task context or test report; no external-future model → adaptation choice → capability-configuration feedback. - Why this is / is not agent-owned: Persistence, task planning and model fallback are not sufficient for future-facing organizational intelligence. - Evidence: context management, planner instructions, CLI evaluation. - Basis: bounded structural absence. - Confidence: High. - Caveats: External builders could use benchmarks and workflow reports to guide future strategy, but that is not a first-party installed feedback path.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No first-party ultimate-purpose or identity dispute arbitration beyond per-operation permission rules and human action consent. - Disturbance / variety regulated: Unsafe tool arguments, writes, external MCP calls, destructive execution and untrusted input. - Decisive decision or feedback right: Operator configures policies and human approves particular side effects; no packaged S5 actor decides durable system purpose or constitutional boundaries. - Decision owner: External operator/human for static permission config/individual approval, deterministic policy engine for enforcement. - Supporting / enforcement mechanisms: Allow/deny/require-approval categories, persistent approvals, workspace sandbox and secret redaction. - Closure path: Tool request → permission check or human approval → execute/deny/resume, not identity-level dispute → legitimate ultimate authority decision → enduring organizational mandate. - Why this is / is not agent-owned: Model cannot override tool policy, and approvals are narrow operational gates, not ultimate policy identity choices. - Evidence: permission engine, human approvals, README boundaries. - Basis: bounded structural absence. - Confidence: High. - Caveats: User&#39;s external organization may have its own S5 beyond this library.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/7eb41a76f082be5690ca12269cc1eec41aa5a528/assessments/lo/loopsmith.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 7eb41a76f082be5690ca12269cc1eec41aa5a528\">7eb41a7 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-05T21:00:30+03:00\"><th scope=\"row\"><a href=\"https://github.com/rubin-johnson/maestro\" target=\"_blank\" rel=\"noopener\">Maestro</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/rubin-johnson/maestro/tree/0589ff3b2b0d25baabff196a1dd64c2147048b8e\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 0589ff3b2b0d25baabff196a1dd64c2147048b8e\">0589ff3 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Code-changing task agents implement specified work units and respond to source/tool feedback. - Disturbance / variety regulated: Requirements, repository state, build/test failures, model response and review-requested revisions. - Decisive decision or feedback right: Implementation CLI-backed model selects coding steps and edits; revision requests lead to a new model-driven implementation attempt. - Decision owner: Launched model-driven implementer for local coding decisions, installed into Maestro&#39;s first-party work-unit execution route. - Supporting / enforcement mechanisms: tmux isolation, explicit work-unit spec/DoD, task limits, SQLite persistence, CLI backends and escalation. - Closure path: User work unit→Maestro spawns implementer→model edits repo files→tests/review results→model revision or final accepted code. - Boundary reachability: execute CLI and orchestrator instantiate real tmux coding agents with configured backends, not just mock or planned actors. - Why this is / is not agent-owned: Model actor exercises task-level file-change choice; Maestro&#39;s fixed phase machine supplies gates, not coding autonomy. External vendor CLI internals are not separately credited. - Evidence: orchestrator, tmux manager, CLI. - Basis: Shipped runnable model-directed coding process with corrective feedback into implementation. - Confidence: Medium-high for first-party route; provider runtime effectiveness not independently replayed. - Caveats: Actual model steps run in separately installed CLI products; first-party evidence is their orchestration contract and returned status, not vendor-harness architecture.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No separate agent-owned regulation of specifically observed contention between parallel S1 implementation units. - Disturbance / variety regulated: Dependency readiness, parallel-file collisions and worker resource contention can occur across work units. - Decisive decision or feedback right: DAG dependency checks and maxconcurrent=4 semaphore select ready waves, but are deterministic ordering, not balancing of detected competing goals. - Decision owner: Operator for work-unit DAG; Python scheduler for static ordering and concurrency gates. - Supporting / enforcement mechanisms: Dependency graph, parallel executor, work-unit status, file scope checks and tmux windows. - Closure path: Predeclared dependency→ready/blocked status; parallel work-unit results→output records, not peer contention evidence→autonomous S2 arbitration→returned adjustments. - Why this is / is not agent-owned: A queue, DAG and semaphore are supporting coordination machinery but no distinct real-time S2 balancing authority is installed. - Evidence: workflow executor, parallel executor. - Basis: Bounded absence despite distinct simultaneous work units. - Confidence: Medium-high. - Caveats: Operator can encode dependencies to avoid conflict; not a self-sensing inter-S1 balancing loop.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No model/agent-owned discretionary whole-system management of current operating commitments and resources beyond the authored work-unit sequence. - Disturbance / variety regulated: Failed unit, bad test result, model timeout, context exhaustion and blocked dependencies. - Decisive decision or feedback right: Fixed phase gates and escalation ladder retry/fail/advance per unit; code selects ready waves. Model-assisted decomposition serves task shaping, not a portfolio manager with authority over organizational tradeoffs. - Decision owner: User defines work-unit specs/priority/dependencies; deterministic orchestrator follows configured rules. - Supporting / enforcement mechanisms: Validator gates, model-tier escalation, retry budget, SQLite status, DAG and GitOps. - Closure path: Unit failure→preset retry/tier escalation; DAG dependency blocking→recorded status. No autonomous whole-portfolio capacity/priority/commitment renegotiation. - Why this is / is not agent-owned: Enforceable resource and quality gates are not an independent S3 deciding strategic current tradeoffs; reviewers judge claims, they do not manage fleet priorities. - Evidence: phase and escalation machine, escalation rules, decomposition. - Basis: Bounded absence after testing source-backed execution governance against S3 discretion threshold. - Confidence: Medium-high. - Caveats: A future user/controller could wrap Maestro in a portfolio S3, but the standard execution mode owns only per-unit rule machinery.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: Bounded independent code/spec reality check of implementation claims with a returned review verdict and enforced rework. - Claim being audited: Implementer asserts its work unit meets the original spec and Definition of Done and presents changed files/output. - Ordinary reporting path: Implementer process completion text, status, staged changes and routine command/test output feed the orchestrator. - Complementary access path: Fresh cross-model reviewer agents receive the original spec/DoD and are asked to inspect actual code files and Git diff independently; deterministic validator directly executes source/test checks rather than trust self-report. - Independence boundary: Reviewer runs in a distinct tmux agent session and model type selected to avoid collision with implementer, but uses the same local repo and is orchestrated by Maestro; no external institution or externally verified truth guarantee. - Who acts on findings: Orchestrator parses NEEDSREVISION and validation failure, blocks commit and re-enters implementation or escalates model tier; positive evidence can advance to commit. - Disturbance / variety regulated: Hallucinated completion, incomplete DoD, out-of-scope file changes, security/code-quality defects and misleading model claims. - Decisive decision or feedback right: Reviewer may reject implementation with file:line evidence, while independent validator can fail executable checks; orchestrator enforces corrective loop. - Decision owner: Distinct reviewer model owns evidence-based audit judgment; deterministic validator owns command-based test gate; orchestrator routes returned finding. - Supporting / enforcement mechanisms: Fresh reviewer prompt, different agent type, direct source access, git diff, file-scope manifest, test execution, verdict parser and retry/escalation. - Closure path: Implementer completion claim→fresh independent reviewer reads code/spec (plus test execution/diff)→verdict→orchestrator rejects/requests revision or accepts/commits→new implementation attempt. - Boundary reachability: The shipped review phase spawns its own tmux reviewer, sends actual work-unit spec/diff/file-scope instructions and persists result; source tests cover review/revision behavior. - Why this is / is not agent-owned: The reviewer challenges original operational claims with a separately acquired direct file view, not just repackaged implementer prose. The static accept/deny state machine is an enforcement channel. - Evidence: review creation and non-colliding model selection, reviewer instruction, orchestrator revision path, validators. - Basis: Source-traced alternative direct-code reality access, distinct judgment owner and closed returned correction in normal work-unit mode. - Confidence: Medium-high for implemented bounded audit route. - Caveats: Reviewers can err, share upstream tool vulnerabilities or be manipulated by inputs; using a different model does not alone prove independence, and this is not certified external audit.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No autonomous future-environment sensing and strategic organizational change loop. - Disturbance / variety regulated: Changing model quality/prices, future source architecture, toolchain updates and novel task types. - Decisive decision or feedback right: Operators configure ladder/backend; predictive risk, preflight and dynamic decomposition serve a current task&#39;s execution, not future organizational strategy. - Decision owner: External developer/operator for long-horizon capability changes; per-unit implementer/reviewer for present work. - Supporting / enforcement mechanisms: Provider ladder, cost tier, prediction, knowledge-base roadmap and context-budget monitoring. - Closure path: Failure→current retry with a stronger model; offline future development remains manual. No external scanning→future options→policy/operational mandate adjustment. - Why this is / is not agent-owned: Changing model tier in response to immediate test failures is operational retry, not adaptive prospective environmental intelligence. - Evidence: model escalation, prediction, orchestrator. - Basis: Bounded absence review. - Confidence: High. - Caveats: User can ask Maestro to implement a future plan, which is task-level S1 rather than its organizational S4.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No legitimate ultimate identity-policy governing body or returned parent-assisted mandate. - Disturbance / variety regulated: Unsafe code changes, permission policy, task scope and model/provider credentials. - Decisive decision or feedback right: User authors work spec/DoD, mode, policies and credentials; validator/reviewer enforce work acceptance rather than determine organizational identity. - Decision owner: Operator/developer for legitimate policy; deterministic gates and reviewer for local task acceptance. - Supporting / enforcement mechanisms: Manifest scope, approval mode, preflight DoD quality, explicit backend configuration and commit gate. - Closure path: User spec/config→bounded operational checks; no identity-level conflict→legitimate charter deliberation→binding mandate into S3/S4. - Why this is / is not agent-owned: Security and acceptance criteria around a work unit do not constitute self-directed ultimate governance. - Evidence: preflight, review, config. - Basis: Bounded absence review. - Confidence: High. - Caveats: A human owner may be S5 of a deploying team, but not installed as an autonomous or parent-governed Maestro role.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/466587e24fbc9020d697440ea720db9274be8207/assessments/ru/rubin-johnson-maestro.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 466587e24fbc9020d697440ea720db9274be8207\">466587e &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-05T21:29:46+03:00\"><th scope=\"row\"><a href=\"https://github.com/BlackJaxDev/local-agent-broker\" target=\"_blank\" rel=\"noopener\">Local Agent Broker</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/BlackJaxDev/local-agent-broker/tree/86b09380e3393126d6c540787a7576a61d21565b\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 86b09380e3393126d6c540787a7576a61d21565b\">86b0938 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Model-controlled workers transform bounded objectives into answers, tool-mediated effects, or code-change proposals. - Disturbance / variety regulated: Uncertain objectives, changing tool results, failed or denied calls, and code-edit details in authorized source files. - Decisive decision or feedback right: The provider model selects its response, tool calls and next steps within broker-enforced limits; swarm leaves choose concrete source replacements. - Decision owner: External API model invoked as the active autonomous actor through the first-party broker loop; in swarm mode the per-phase root/leaf models choose plan and edits. - Supporting / enforcement mechanisms: MCP transport, exact-model check, prompt construction, tool registry, immutable snapshots, budgets, provider retries, session policy and parallelism semaphores. - Closure path: Caller starts a run → model chooses answer/tool action → broker executes allowed tool → result returns on the next model turn → completed answer; in swarm mode leaf proposals return through review and caller-controlled apply. - Boundary reachability: startagentrun invokes AgentRunRegistry.Start and AgentOrchestrator.RunAsync; optional swarm routes through RunSwarmAsync/RunNodeAsync in shipped production code, not a test-only agent. - Why this is / is not agent-owned: The model decides task content/actions. Hard tool caps and file permissions only constrain or reject those decisions, rather than replacing their discretion. - Evidence: MCP tool implementation, agent turn/tool feedback, swarm leaves. - Basis: Structural first-party model-execution and feedback path. - Confidence: High for code wiring; medium for real provider execution because no billed run was repeated here. - Caveats: A standalone broker invocation still needs explicit provider credentials and client authorization; provider cognition is not itself first-party broker implementation.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No established adaptive inter-S1 conflict/oscillation attenuation with returned behavioral adjustment in the shipped modes. - Disturbance / variety regulated: Parallel child agents can propose overlapping edits to a shared source file; separately queued workers can contend for concurrency capacity. - Decisive decision or feedback right: The caller fixes allowed paths and limits; deterministic merger rejects overlapping source edits rather than negotiating a revised peer coordination response. - Decision owner: Caller for path allocations/limits; root model for initial task decomposition; runtime for conflict validation and static semaphore enforcement. - Supporting / enforcement mechanisms: Per-child path assignment, immutable base hashes, overlap rejection, provider-slot and swarm-slot semaphores. - Closure path: Parallel child edits → conflict checker either combines non-overlapping patches or fails the proposal; no installed conflict-resolution decision goes back into a new coordinated child round. - Why this is / is not agent-owned: Distinct S1 leaves and a real possible edit collision are present, but a rejection gate and initial delegation are not an S2-specific feedback regulator changing subsequent inter-S1 behavior. - Evidence: plan constraints, overlap detection, parallel execution. - Basis: Bounded negative functional assessment despite a structurally identifiable disturbance. - Confidence: Medium-high. - Caveats: External callers could retry with changed scopes; such a coordination actor/loop is not installed in the broker itself.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No autonomous whole-system current-control authority over a portfolio of active work and shared commitments beyond bounded delegation rules. - Disturbance / variety regulated: Provider failures, spending/turn/tool budgets, child-run admission, timeout and cancellation. - Decisive decision or feedback right: Caller fixes model, task, tool permissions and budgets; swarm root generates a one-time file-scoped task plan, while the runtime enforces ceilings and aborts on failure. - Decision owner: Caller/operator owns shared limits and resource policy; model&#39;s root plan owns current task decomposition, not ongoing organizational capacity or commitments. - Supporting / enforcement mechanisms: AgentRunRegistry, global concurrency, AgentRunBudget, per-phase token reservation, node admission caps, failure propagation and status registry. - Closure path: Preset limits → runtime admission/scheduling/termination; the shipped loop lacks a whole-run current-state appraisal feeding discretionary reallocation of operational commitments. - Why this is / is not agent-owned: Model task splitting is not evidenced whole-system current-resource bargaining or authoritative intervention; semaphores/budgets enforce caller choices. - Evidence: run registry, swarm plan, limits and failure propagation. - Basis: Bounded negative after testing root-orchestrator and runtime-manager paths. - Confidence: Medium-high. - Caveats: Host clients may provide higher-recursion fleet S3; their decisions are outside this broker&#39;s boundary.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: Bounded model-owned source-backed review of child agent code-change claims before approval or application. - Claim being audited: Each leaf&#39;s proposed replacement is a valid contribution to the parent objective and success criteria. - Ordinary reporting path: Leaf model emits JSON path, basesha256, oldtext and newtext; runner collects child artifacts. - Complementary access path: A fresh parent review API request receives the unchanged child artifacts and broker-captured immutable source snapshots and original objective, not only the leaf&#39;s completion assertion. The deterministic merger separately validates base hashes/overlap. - Independence boundary: The review runs as a distinct provider phase after leaves finish, without their continuation or permission to modify their artifacts; the child cannot mark its own edits approved. The same exact model/provider family may be used and all inputs are broker-supplied snapshots, so this is bounded internal complementary inspection, not cross-model or external institutional audit. - Who acts on findings: RunNodeAsync rejects the entire swarm when the parent model returns approved=false; only positive review returns proposals to the run registry for caller review or explicit Windows application. - Disturbance / variety regulated: Plausible but faulty code replacements, mismatch to objective and misleading leaf success claims. - Decisive decision or feedback right: Separate parent reviewer model decides approved and summary after examining source and unchanged proposed edits; deterministic orchestrator enforces that verdict. - Decision owner: Review-phase provider model makes the substantive accept/reject judgment; runner parser and fail path are supporting enforcement. - Supporting / enforcement mechanisms: Immutable source snapshot capture, isolated phase request with no tools, review-specific instructions, JSON parse, merge collision check and no-change-on-rejection guard. - Closure path: Leaf proposals → fresh model review with original source/artifacts → verdict → rejection terminates with no approved changes, or approval exposes the proposal for caller acceptance and possible readback-checked application. - Boundary reachability: Optional production swarm uses RunNodeAsync for every orchestrator node, creates a distinct CreatePhaseRequest with context-file snapshots for review, and RunSwarmAsync exposes only approved changes. - Why this is / is not agent-owned: The reviewer independently judges a source-backed child claim rather than trusting its self-report; the deterministic parser does not supply the substantive review decision. - Evidence: review request and input wiring, review verdict closure, provider snapshot input, rejection test. - Basis: Structural distinct audit-judgment call with source evidence and returned corrective veto. - Confidence: Medium: model decision and wiring established in source; actual provider-backed judgments not replayed. - Caveats: Same model/provider can produce correlated errors; review sees captured source and proposals, not independently sampled live post-apply code. This is not a general-purpose S3 of all broker runs.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No shipped external/future environmental sensing, option formation, and adopted adaptation loop for the broker itself. - Disturbance / variety regulated: Changing provider options, future model costs/capabilities, repository evolution and new threats. - Decisive decision or feedback right: Caller selects actual model/configuration; keyword-based route advisor can recommend a model for the current objective, not revise future organizational capability. - Decision owner: Human caller/developer for model/policy upgrades; deterministic AgentRouteAdvisor for present-task recommendation. - Supporting / enforcement mechanisms: Exact-model catalog, task keyword classifier, provider error/retry diagnostics and operator settings. - Closure path: Current objective → static model recommendation → caller choice for this run; no external sensing→prospective options→capability adoption path. - Why this is / is not agent-owned: Task difficulty routing and provider retries respond to current execution, not environmental foresight or adopted future change. - Evidence: route advisor, broker config, run/model validation. - Basis: Bounded negative after route/adaptation candidates were inspected. - Confidence: High. - Caveats: A user may delegate future-looking research to an individual worker; that is operational S1 output, not an established broker-level S4.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No ultimate identity/policy deliberation and legitimate return-to-runtime decision loop at this broker recursion. - Disturbance / variety regulated: Task authority, source-file permissions, credential exposure, destructive editor commands and uncontrolled billed model execution. - Decisive decision or feedback right: Caller and configuration supply boundaries; deterministic validators reject unauthorized requests. There is no shipped identity/charter question escalated to and resolved by an ultimate authority with a returned mandate. - Decision owner: External MCP caller/operator for task authorization and security policy; program validators enforce rather than govern its content. - Supporting / enforcement mechanisms: Explicit workspace/allowed paths, tool annotations and allowlist, destructive/mutation flags, exact model requirement, budget checks and secret-path denial. - Closure path: Operator-supplied scope → fixed request guards → permitted/denied run; no identity-level issue→legitimate parent authority→binding policy decision→changed subsequent operation. - Why this is / is not agent-owned: Ordinary permissions and operator review of a patch are run-level controls, not a first-party S5 organization or parent-governed identity loop. - Evidence: protocol policy, repository path policy, run admission. - Basis: Bounded negative for the standard-distribution authority path. - Confidence: High. - Caveats: The parent organization using the broker may have an S5; its external decisions are not part of this local harness&#39;s evidenced operating structure.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/a8b7d8aa1af85fabe5957742ed23c9358007621d/assessments/lo/local-agent-broker.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit a8b7d8aa1af85fabe5957742ed23c9358007621d\">a8b7d8a &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-05T17:29:23+03:00\"><th scope=\"row\"><a href=\"https://github.com/Open-RUA/uni-robot-agent\" target=\"_blank\" rel=\"noopener\">Uni Robot Agent</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/Open-RUA/uni-robot-agent/tree/2590ab48b7c24a72123597f2d5b04c9524e4329c\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 2590ab48b7c24a72123597f2d5b04c9524e4329c\">2590ab4 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomous task execution through repeated robot observation, tool/action choice and resulting environmental feedback. - Disturbance / variety regulated: changing object poses, grasp failures, occluded views, tool errors, unavailable resources and differences between expected and measured effects. - Decisive decision or feedback right: the configured coding-agent model chooses which available robot tool to call, with what arguments, whether to inspect/recover and when to request finish. - Decision owner: model-backed Codex/Claude task agent in the shipped run/TUI session; the SDK and provider implement its inference, while the first-party harness wires its decisions to robots. - Supporting / enforcement mechanisms: first-party MCP/Claude tool adapters, shared Episode, resource executor, snapshots, action-size bounds, state-version checks, receipts, time/step budgets and structured feedback. - Closure path: task instruction and scene → model chooses a registered tool → executor/environment performs or rejects a bounded action → result, image and updated state return into the agent&#39;s next decision → task continues or finishes. - Boundary reachability: session.py actually selects and invokes a packaged Codex/Claude adapter with registered tools; no separate operator-authored control program is necessary after starting the supported model-backed episode. - Why this is / is not agent-owned: the agent has genuine contextual discretion among actions and recovery steps; deterministic guards and robot services restrict or carry out those choices but cannot replace the agent&#39;s task decisions. - Evidence: main run cycle, Claude SDK run and tool interaction, Codex SDK run, tool/episode flow. - Basis: structural code and explicit shipped run documentation; no live model-provider run was claimed in this review. - Confidence: high for the supported agent-to-tool/feedback decision path; physical task success remains unverified here. - Caveats: the model/SDK must be installed and configured; such dependencies do not make the first-party integrated agent path merely a non-agentic tool library.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no distinct inter-S1 conflict-attenuation relation was established at the declared episode recursion. - Disturbance / variety regulated: concurrent motion/tool calls can conflict over an arm, an episode or its state version, but the reviewed paths serialize tools of one task-agent&#39;s execution rather than reconcile distinct autonomous S1 units. - Decisive decision or feedback right: configured FIFO resource placement and immutable-snapshot rules govern tool execution; no first-party autonomous inter-S1 adjustment choice was found. - Decision owner: deterministic scheduler/developer configuration, not an S2 agent decision owner. - Supporting / enforcement mechanisms: ToolExecutionPolicy, per-resource exclusive queues, background job handles, global-serial option and SDK subagent support. - Closure path: incompatible calls wait for a resource and receive completion feedback, but this is intra-episode execution safety, not a separately evidenced cross-S1 coordination conversation. - Why this is / is not agent-owned: SDK-native subagents and two physical arms do not by themselves establish two organizational S1 units with their own outcomes and a specific reciprocal disturbance. - Evidence: scheduling and resource semantics, scheduler, agent adapter boundaries. - Basis: bounded negative inspection of shipped robot-tool and agent delegation modes. - Confidence: medium-high at the episode boundary. - Caveats: a separate multi-robot or multi-agent deployment might establish S2, but that composition is not inferred from SDK capability.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no independent whole-system current-control owner over multiple S1 commitments/resources was established. - Disturbance / variety regulated: running time, token/tool limits, physical safety, stale observations and missed action acknowledgements are regulated locally within an episode. - Decisive decision or feedback right: operator/developer selects budgets and modes; runtime rejects/queues/cancels actions according to those constraints, while the task agent chooses local work. - Decision owner: configuration/episode executor, not a distinct metasystem owner with current whole-system bargaining discretion. - Supporting / enforcement mechanisms: timeout, step limit, resource queues, receipts, cancellation and TUI/CLI status. - Closure path: bounded local execution and failures feed the same agent&#39;s continuation; no portfolio-level current resource decision returns to several operational units. - Why this is / is not agent-owned: calling the executor a controller does not establish S3; it does not independently allocate/revise commitments across an operational whole. - Evidence: session lifecycle, scheduler, architecture. - Basis: bounded absence review of implemented execution-control and user modes. - Confidence: medium-high. - Caveats: parent human instructions and operational safety guards are real, but neither automatically closes S3 at this recursion.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: an opt-in independently prompted model checks a subordinate VLA&#39;s proposed motor-action chunk against current raw observations, measured state and expected task progress, then can require a correction or stop before execution. - Disturbance / variety regulated: the Pi action model can propose an unsafe, geometrically misaligned or already-completed prefix despite producing a normal-looking trajectory. - Decisive decision or feedback right: reviewer model selects student, edit, eef or stop, number of steps, reason and continuation after judging the proposal and physical evidence; ActorRunner uses this decision to execute, modify or withhold the proposed chunk. - Decision owner: the separately invoked VLA reviewer model in supported RoboDojo Hybrid reviewer-enabled mode; deterministic validation/bounds constrain, but do not choose, its evaluative verdict. - Supporting / enforcement mechanisms: fresh camera capture, measured state and FK proposal, separate reviewer prompt/Responses call, structured validator, chunk archive, bounded correction commands and execution receipts. - Closure path: Pi proposes action prefix → independent reviewer receives proposal plus raw/derived observation → reviewer returns corrective or stop judgment → ActorRunner changes executed commands or halts → actual feedback and previous review enter the next chunk or higher-level task agent. - Boundary reachability: the shipped --action-profile hybrid path constructs ChunkReviewer by default when binding supports it, requires an explicit Responses-compatible endpoint, and calls its decide before any chunk execution. It is not a paper-only evaluator or an uninstalled CI process. - Why this is / is not agent-owned: the reviewer can counter the subordinate actor&#39;s suggestion with independent discretionary evidence assessment and corrective action; it is not simply a deterministic success flag. This is mode-specific and cannot be generalized to Direct mode or to unconfigured endpoints. - Claim being audited: the proposed VLA action is aligned with current physical observations, task intent and local progress, and its continuation is warranted. - Ordinary reporting path: VLA proposal/trajectory and main task agent&#39;s instruction/task-progress report. - Complementary access path: separately prompted reviewer model sees raw head/wrist camera images, measured pose/FK checks, native feedback and prior reviewer context before command commitment. - Independence boundary: the VLA does not choose or edit the review verdict; the reviewer call has distinct prompt/context and can veto/correct, although the same provider/model family may be configured and both remain inside one product&#39;s action path. - Who acts on findings: ActorRunner applies stop, altered command prefixes or continued student actions; the main agent receives final tool feedback for its next choice. - Evidence: reviewer decision model, source-grounded reviewer prompt, execution after verdict, reviewer enablement. - Basis: structural first-party review/judgment and actuation-return wiring; no separate provider E2E was performed. - Confidence: medium for materially complementary access, high for the executable verdict-to-command decision path. - Caveats: no assurance of model reliability or institutionally independent review follows. Hybrid requires a model endpoint, action checkpoint and integration. This state credits the installed optional reviewer path, not routine task success checks or offline evaluation.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no demonstrated first-party outside-and-prospective option-selection conversation returning to current whole-episode capability was established. - Disturbance / variety regulated: future environments, robot geometries and repeated failures could motivate improved skills or action models. - Decisive decision or feedback right: writeskill optionally lets the task agent store an observed lesson in an operator-configured external library; developers choose model/integration updates. Neither shows a separate established future-environment intelligence and S3 adaptation loop. - Decision owner: task agent owns local lesson text when enabled; operator/developer chooses whether/how to reuse broader configuration and model improvements. - Supporting / enforcement mechanisms: opt-in skill-writing, read/list skill tools, prompt guidance that requires evidence and narrow transfer, saved traces and optional SFT export. - Closure path: a verified task lesson may be stored for a later run, but review found no first-party prospective external-option decision with a defined whole-system capability adoption/return path; ordinary memory reuse is not sufficient. - Why this is / is not agent-owned: experience preservation can alter later task context, but it is not by itself S4&#39;s external-and-then intelligence conversation. - Evidence: skill-writing implementation, lesson instructions, architecture&#39;s optional skill mode. - Basis: bounded negative review distinguishing operational experience from prospective environmental adaptation. - Confidence: medium; externally oriented future modes may be added later. - Caveats: this does not deny useful cross-run skill improvement or possible future S4 constructor work.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no legitimate runtime identity/ultimate-policy issue-to-authority-to-operation loop was established. - Disturbance / variety regulated: conflicts over robot-task safety, data/model choice, user purpose and deployment policy could raise higher-level identity questions, but these remain outside the reviewed episode governance. - Decisive decision or feedback right: a user chooses task/mode/constraints; first-party runtime enforces tool permissions and safety bounds, without a distinct S5 deliberation/return path. - Decision owner: external human/project authority for product identity; task-local model/guard machinery does not own ultimate policy. - Supporting / enforcement mechanisms: CLI configuration, model/tool permissions, tool restrictions, explicit finish acknowledgement and environment safety state. - Closure path: configuration constrains next actions and safety checks reject disallowed movement; no observed identity dispute is escalated to a legitimate parent and returned as a revised binding ultimate policy. - Why this is / is not agent-owned: human task instructions and deterministic safety policy do not become autonomous or parent-governed S5 merely because they are authoritative for one episode. - Evidence: configuration, run structure, episode and tools. - Basis: bounded negative inspection of runtime control, human interaction and governance scope. - Confidence: medium-high at the declared episode boundary. - Caveats: the external robotics organization may possess its own S5; it is not part of this first-party deployed harness by repository adjacency.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/b1c0dda8f43c21cc9cbab1d1db5c651a537454d4/assessments/un/uni-robot-agent.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit b1c0dda8f43c21cc9cbab1d1db5c651a537454d4\">b1c0dda &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-05T20:07:24+03:00\"><th scope=\"row\"><a href=\"https://github.com/phuryn/mini-harness\" target=\"_blank\" rel=\"noopener\">Mini Harness</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/phuryn/mini-harness/tree/7ae9fca8221c55bd3c38697a61075357e1a94c26\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 7ae9fca8221c55bd3c38697a61075357e1a94c26\">7ae9fca &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Model-guided local work with iterative tool-result feedback. - Disturbance / variety regulated: Changing files, shell command outputs, tool errors, user objectives and MCP responses. - Decisive decision or feedback right: Model chooses next tool and arguments after observations, can stop or delegate a bounded reading task. - Decision owner: Model executing in first-party Agent.turn/dispatch; installed harness executes selected calls. - Supporting / enforcement mechanisms: LocalTools, approvals, MCP hub, append-only session, context compaction and goal mode. - Closure path: User/goal → model inference → selected local/MCP tool → real result → appended observation → another model choice or answer. - Boundary reachability: Supported CLI instantiates an actual model client and supplies tools; fake-model tests exercise the same loop, but paid-provider operation was not replayed here. - Why this is / is not agent-owned: Model is able to choose an action and change it from observations; tool runtime and permissions do not own the choice. - Evidence: loop and dispatch, tools, session. - Basis: First-party model→tool→observation→redecision implementation and reachable CLI. - Confidence: High for code path; no paid-provider E2E claim. - Caveats: Provider behavior, external MCP cognition and human permission remain outside first-party ownership.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No ongoing regulation of contention between multiple autonomous operational S1 units is installed. - Disturbance / variety regulated: Parallel demands or access conflict among distinct workers could arise, but task delegates a standalone reading request rather than balancing competing S1 commitments. - Decisive decision or feedback right: Main agent may delegate; no independent conflict arbitration loop decides inter-worker priorities. - Decision owner: Main S1 model for delegation and operator for permission; none for a separate S2. - Supporting / enforcement mechanisms: Fresh-session task subagents, tool approval and session separation. - Closure path: Main model→child task→child text→main model; no discovered contention→S2 arbitration→corrected peer commitments path. - Why this is / is not agent-owned: Sequential or concurrent delegation is not itself feedback regulation between S1 units. - Evidence: subagent invocation, session. - Basis: Bounded absence review of installed delegate and tool gates. - Confidence: High. - Caveats: User-built external MCP servers might coordinate their own agents outside this boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: No discretionary control of present resources, priorities and commitments across a whole set of autonomous S1 operating units. - Disturbance / variety regulated: Goal turn/budget exhaustion, failed verification, tool risk and paused work. - Decisive decision or feedback right: /goal performs fixed turn/budget/status gates and deterministic pass-or-retry; users choose the verification command and budget. - Decision owner: Human operator owns scope/budgets; code enforces fixed conditions. Main model still owns task steps. - Supporting / enforcement mechanisms: rungoal turn limit, spend meter, verify, permission approval and pause/resume. - Closure path: Claimed completion→verification/reviewer gate→accept or return disagreement to same S1; no discretionary cross-unit resources/commitment management. - Why this is / is not agent-owned: Strong operational gating does not itself imply a separate S3 decision authority over an S1 portfolio. - Evidence: goal and verification, permission gate. - Basis: Bounded current-control absence despite a real goal-acceptance gate. - Confidence: Medium-high. - Caveats: A separately deployed fleet supervisor could add S3, but is not a first-party standard mode here.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: Separate fresh-context inspection of a worker&#39;s completion claim using additional operational evidence before accepting a goal. - Claim being audited: The main model declares that the current /goal objective is fully complete and supplies goaldone evidence. - Ordinary reporting path: The worker&#39;s tool observations and self-reported completion argument arrive through its existing session and goal claim. - Complementary access path: Fresh-context reviewer receives the objective and claim and can directly inspect current working-directory files using its own tool calls; optional shell verifier independently executes user-specified checks. - Independence boundary: Distinct reviewer session and tool calls but the same first-party code/provider client and host permission policy; reviewer is not a separately governed institution. - Who acts on findings: Agent.rungoal rejects unapproved completions, returns negative reviewer findings to worker and repeats until accepted or stopped. - Disturbance / variety regulated: False self-reported completion, missing/incorrect local artifacts and a worker&#39;s biased summary. - Decisive decision or feedback right: Reviewer independently reads working-directory evidence and returns VERDICT: DONE or rejection; goal controller accepts only a positive verdict after optional independent shell verification. - Decision owner: Fresh reviewer model for the audit judgment; harness for deterministic acceptance and rework routing; operator for optional verify definition. - Supporting / enforcement mechanisms: New reviewer session, actual LocalTools read/bash access, distinct review instructions, optional shell verify, literal verdict parser and rework prompt. - Closure path: Worker goaldone claim→independent shell check when configured→new reviewer reads workspace→review judgment→goal controller acceptance or discrepancy returned to worker→corrective next turn. - Why this is / is not agent-owned: Reviewer receives the goal and claim but has a genuinely separate workspace observation path and can reject the claim, rather than merely grading its prose; the gate only enforces the decision. - Evidence: REVIEW, runsubagent, rungoal, verify, reviewer false-claim test. - Boundary reachability: Supported /goal invokes verify on goaldone; bundled tests cover rejection, retry and fresh reviewer tools, without requiring a hypothetical external plugin. - Basis: Source-traced complementary evidence access, separate judgment, explicit corrective return in supported /goal mode. - Confidence: Medium-high for installed bounded path, not independent external audit quality. - Caveats: Same provider/client and workspace permissions; reviewer may be wrong, can be influenced by claim text, and is triggered by worker&#39;s completion claim. Independence is complementary to the worker&#39;s ordinary report, not organizational or institutional independence.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No autonomous prospective environment-scanning and strategy/adaptation cycle for the harness organization. - Disturbance / variety regulated: Model availability, new skills and MCP sources, changing user needs and context size. - Decisive decision or feedback right: Human configures external services and models; compaction summarizes current conversation and goal remains a current task. - Decision owner: Operator for future capability selection, present S1 for ordinary research within user request. - Supporting / enforcement mechanisms: Skills, MCP discovery, model presets, compaction, session resume and subagent research. - Closure path: Updated config or task findings may change next operation; no future-environment forecast→strategic selection→adopted change in S3 operations. - Why this is / is not agent-owned: Compaction/memory and delegated investigation support present tasks without autonomous mandate to reconfigure future capacity. - Evidence: loop/model config, external service hooks. - Basis: Bounded absence review. - Confidence: High. - Caveats: Individual agent may discuss future scenarios as an S1 user task.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No distinct ultimate identity-policy or parent-governed mandate cycle in the installed task harness. - Disturbance / variety regulated: Permission-sensitive requests, unsafe tool invocations and operator goal changes. - Decisive decision or feedback right: Operator approves/denies risky actions and sets goal; optional cheap-model permission judge recommends local allowances under a fixed gate. - Decision owner: External user and static permission rules; no independent legitimate S5 authority. - Supporting / enforcement mechanisms: Approval prompts, optional permission judge, goal entry and local policy/configuration. - Closure path: User/permission decision→tool allow/deny; no identity-level conflict→legitimate policy decision→returned organizational mandate. - Why this is / is not agent-owned: Permission vetting is a task action constraint, not constitutive identity governance. - Evidence: permissions, goal setup. - Basis: Bounded absence review, including model-assisted permission path. - Confidence: High. - Caveats: External organization or human can exercise S5 outside this first-party product.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/f4373c2a406cda6a71e08c5c68ac4810c7d980da/assessments/ph/phuryn-mini-harness.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit f4373c2a406cda6a71e08c5c68ac4810c7d980da\">f4373c2 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"2\" data-assessment-at=\"2026-11-05T21:20:27+03:00\"><th scope=\"row\"><a href=\"https://github.com/genproof/QuickMaths\" target=\"_blank\" rel=\"noopener\">QuickMaths</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>2</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/genproof/QuickMaths/tree/c2dbb59e13b3cce451b86e600345361b34e8c5ba\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision c2dbb59e13b3cce451b86e600345361b34e8c5ba\">c2dbb59 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Transform a mathematical problem or contracted proof lane into proof artifacts through successive agent choices and compiler observations. - Disturbance / variety regulated: Open proof holes, library availability, compiler errors, failed tactics, quota limits and continued work. - Decisive decision or feedback right: Choose mathematical steps, edits, searches and next proof tactics within the supplied problem/lane contract. - Decision owner: Model-driven proving agent in the concrete first-party prepared job/role composition. - Supporting / enforcement mechanisms: Pinned external Claude Code executes model rounds; first-party agentrunner, Landlock boundary, ./lean broker, snapshots, role briefs, budgets and continuation sustain them. - Closure path: Prepared job/brief launches the pinned CLI with workspace tools; ./lean returns build/search/inspect observations; later edits/rounds consume those observations and retained notes/artifacts. Official verification alone controls final acceptance. - Boundary reachability: controller prepares and starts the packaged runtime; feeder attaches actual role briefs to assignments. This credits the shipped proving composition, without borrowing unrelated Claude Code functions. - Why this is / is not agent-owned: Removing the model-driven prover leaves supervision and compilation but no choice of proof construction or repair. - Evidence: fleet/server/controller.py; runtime/leaneval/jobs.py; runtime/leaneval/agentrunner.py; runtime/leaneval/worker.py; fleet/server/briefs/COMMON.md - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:1\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S2 / coordination: - State: A - Function: Regulate conflicting interfaces and duplicate shared machinery among concurrent proof-lane S1 cells. - Disturbance / variety regulated: A consumer needs a stronger producer statement, a lane refutes a shared assumption, or consumers independently re-derive incompatible shared machinery. - Decisive decision or feedback right: Architect grants/refuses interface requests, revises producing/consuming contracts and preserves only still-valid finished lanes. - Decision owner: The model-driven ARCHITECT/REARCHITECT agent at the lane-program coordination boundary. - Supporting / enforcement mechanisms: Lane write confinement, InterfaceRequests/refutation extraction, validated reductions/sanity statements, bounded rearchitecture, merged overlays and redispatch enforce and transport the chosen response. Fleet de-duplication is an additional deterministic path, not the agent owner. - Closure path: LANE writes a concrete request/refutation; feeder collects it and supplies findings to a later architect; architect chooses corrected statements; validated architecture becomes the new base and subsequent lane assignments use those contracts. - Boundary reachability: feeder updateprogram/programassignment wire the shipped role briefs and findings into actual model rounds, then replace active lane state after validation. This is a supported operating path, not contributor dogfood. - Why this is / is not agent-owned: Deterministic code can detect/reforward a mismatch, but cannot choose the corrected mathematical interface or grant/refuse the request without the architect. - Distinct S1 units: Concurrent producer and consumer LANE proof work cells, each with a separate proof outcome and directory. - Inter-S1 disturbance: Consumer requirements exceed producer contracts or a refuted interface invalidates dependent lanes; concrete request/refutation fields and source tests expose this collision. - Attenuating coordination relation: Shared interface contracts, one shared-tool producer, request-to-architect revision and invalidation of dependent completed claims. - Feedback into subsequent S1 behaviour: Corrected architecture replaces lane statements and subsequent dispatched/restarted work uses the new base; invalid consumers cannot remain done. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: The return changes a specific producer–consumer interface conflict rather than merely assigning tasks or transporting results. - Evidence: fleet/server/briefs/roles/ARCHITECT.md; fleet/server/briefs/roles/LANE.md; fleet/server/briefs/roles/REARCHITECT.md; fleet/server/feeder.py; fleet/tests/testfeeder.py - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: - State: C(P) - Function: Regulate current campaign commitments, placement, continuation, competing routes and scarce account/runner resources. - Disturbance / variety regulated: Quota-exhausted work alongside idle usable accounts, duplicated programs, stalled lineages and unsuitable placements. - Decisive decision or feedback right: Select/revise fleet policies and current interventions: hold/release, stop, hand off, split, hedge or rearchitect on behalf of the campaign. - Decision owner: Base C: a developer must compose the discretionary autonomous campaign controller over the specific current-view/plan/inbox/operator interfaces. Parent P: the legitimate campaign experiment manager/operator owns those choices. - Supporting / enforcement mechanisms: Deterministic coordinator.plan/execute, feeder scheduling, inbox outcomes, locks, controlled STOP and quota gates enforce selected constraints; their fixed rules are not autonomous organizational judgment. - Closure path: Gathered fleet status and lane/claim evidence inform manager decisions; --apply/inbox and operator commands change holds, claims, seeds or program architecture; feeder readback and later assignments enact the decision. - Boundary reachability: Deployment docs explicitly expose fleet status, coordinator apply and leh op to the experiment manager. Unlike a generic kill switch, these are campaign-specific current-control interfaces. No automatically running agent manager is shipped. - Why this is / is not agent-owned: With the manager removed, configured rules still enforce preselected policy but do not independently revise campaign priorities. A possible supervised agent session does not establish autonomous ownership of the reserved manager decisions. - Whole-system current view: Coordinator gathers hosts, accounts, live lineages, passes, targets, programs and prior directive outcomes; manager reads campaign status plus residual/quota information. - Current-control decision scope: Cross-host resource/commitment intervention and campaign/program continuation/route decisions, rather than just one proof tool call. - Evidence: fleet/local/coordinator.py; fleet/server/feeder.py; fleet/docs/COORDINATOR-POLICY.md; fleet/operator/README.md; docs/EXPERIMENTMANAGER.md - Basis: structural with explicit documented parent procedure - Confidence: high for P and specific construction surfaces; no A claim - Caveats: C does not grade deterministic scheduling as agent-owned. Parent authority is local to the operated campaign, not the OSS contributor organization.\">C(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: Complement ordinary progress claims with direct proof-graph/statement inspection of a nonconverging program. - Disturbance / variety regulated: Self-reported RESIDUALS estimates can shrink through renaming while actual holes remain; false/vacuous lane assumptions can invalidate apparent progress. - Decisive decision or feedback right: Judge mismatch between agent progress claims and direct Lean declaration/statement reality, then require corrective intervention. - Decision owner: A separately composed experiment-manager auditor; the first-party audit-specific procedure and evidence/control path are supplied, but autonomous auditor execution/authority is not automatically wired. - Supporting / enforcement mechanisms: leh map builds the merged tree and extracts actual reached/sorry-dependent declarations/refutations; operator tools expose artifacts/notes and rearchitect/stop updates. Lean execution and JSON summaries are evidence machinery, not the audit-judgment owner. - Closure path: METHOD §9 requires periodic map-versus-RESIDUALS comparison; the manager stop-and-audit procedure inspects statement truth/source strength and routes findings into rearchitecture/hedges or corrected program briefs through leh op. The direct map is advisory until that actor acts. - Boundary reachability: The installed leh map and deployed operator tools are linked by the supported manager method. It is an intentionally exposed campaign-audit construction, distinct from repository AUDIT.md or mandatory official acceptance. - Why this is / is not agent-owned: The map exposes materially different facts, but does not itself decide or implement the audit judgment; the supervised manager/agent setup remains to be composed for autonomous closure. - Claim being audited: Reported progress/completion and validity/usefulness of lane statements. - Ordinary reporting path: NOTES RESIDUALS/HANDOFF, lane done state and feeder convergence summaries. - Complementary access path: Build the merged proof tree, walk actual Lean declaration reachability/sorry/refutation dependencies, inspect published proof and concrete statement counterexamples. - Independence boundary: Manager does not prove the lanes; direct graph/statement access is outside self-reported estimates. Official verifier alone is not treated as S3. - Who acts on findings: Experiment manager selects corrective stop/rearchitecture/hedge; operator tools return findings to architect and subsequent lane rounds. - Evidence: docs/METHOD.md; docs/EXPERIMENTMANAGER.md; src/harness/map/build.py; src/harness/map/summary.py; fleet/operator/rearchitect.py - Basis: structural - Confidence: medium-high - Caveats: No autonomous always-on auditor is claimed, and this assessment did not run Lean graph extraction. Human-owned audit is not published as P in this Methodology.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S4 / adaptation: - State: P - Function: Develop the campaign capability repertoire from external mathematical/library opportunities under experiment-manager direction. - Disturbance / variety regulated: Upcoming proof ingredients absent from current workbench versus existing licensed formalizations, changed/problematic benchmark statements and future evaluation feasibility. - Decisive decision or feedback right: Choose external reusable sources or revised methods to bring into the proving capability, with human acceptance and rollout. - Decision owner: The legitimate campaign experiment manager; documentation explicitly says a person decides/applies adaptation. A supervised operator agent can assist without establishing autonomous adaptation authority. - Supporting / enforcement mechanisms: Manager literature/web recon and evolve reports support option development; bank add pins/license-checks sources, deploy distributes accepted briefs/policies, and worker search exposes admitted bank entries. - Closure path: Manager compares current convergence/capability gaps with published sources and future campaign needs, chooses reuse/admission or method change, adds pinned formalizations to the durable workbench bank or commits/redeploys approved changes; later architects/lanes search/use them and report reuse. Subsequent reports compare effects. - Boundary reachability: METHOD §§6,8,10 and manager instructions explicitly connect external recon to the bank/briefs; bank.py and worker.py implement the returned capability change. Evolve alone, being retrospective internal analysis, would not establish S4. - Why this is / is not agent-owned: Model proof search and deterministic proposal reports cannot independently approve/admit campaign adaptation; the documented manager remains the decisive parent. - External distinction: Relevant published mathematics/formalizations, benchmark issue information and organizer resource envelope beyond the current proof workspace. - Future / prospective distinction: Whether forthcoming campaign/lane work should reuse new ingredients or change method rather than repeat unsupported construction; durable bank admission changes the repertoire of later rounds. - Adaptation option generated: Acquire a licensed pinned formalization as a reusable tool source, revise role briefs/gates, or retain the current capability after comparison. - Path back into current capability / S3: Manager bank admission makes new sources searchable by the running runtime; accepted policy/brief changes are tested/deployed and used by later fleet assignments. - Evidence: docs/METHOD.md; docs/EXPERIMENTMANAGER.md; docs/EVOLVE.md; runtime/tools/bank.py; runtime/leaneval/worker.py; fleet/server/briefs/roles/ARCHITECT.md - Basis: explicit documented operating procedure plus structural return path - Confidence: medium-high - Caveats: A search for a present proof ingredient alone is S1; credit is limited to the documented manager capability-acquisition/rollout loop. No campaign transcript, measured adaptation benefit or autonomous Director is claimed.\">P</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: Standing safety/source/acceptance rules and a person deciding submission/publication constrain the campaign; no runtime identity/ultimate-policy issue process with legitimate authoritative return is supplied. Experiment-manager current control and approved method updates do not automatically become S5. - Disturbance / variety regulated: No distinct function-specific regulation established at this boundary. - Decisive decision or feedback right: None supplied for this organizational function. - Decision owner: No first-party function owner established. - Supporting / enforcement mechanisms: Static source/credential/acceptance constraints, profile.toml licensing rules, reviewed evolution commits and publish/trust decisions; none establishes a distinct identity-policy deliberation/escalation loop. - Closure path: No function-specific returned regulation; the operational mechanisms remain as described. - Why this is / is not agent-owned: The reviewed mechanisms do not establish the function before ownership classification. - Evidence: docs/EXPERIMENTMANAGER.md; docs/EVOLVE.md; docs/CONFIGURATION.md; runtime/leaneval/resources/profile.toml; fleet/local/publish.py - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/dc4fff62cbaa1faa7b2e604db7a71ece9e95521b/assessments/qu/quickmaths.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit dc4fff62cbaa1faa7b2e604db7a71ece9e95521b\">dc4fff6 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-11-04T13:50:49+03:00\"><th scope=\"row\"><a href=\"https://github.com/beipo-ai/NorthCUA\" target=\"_blank\" rel=\"noopener\">NorthCUA</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-04\">2026-11-04</time></td><td class=\"review-ref\"><a href=\"https://github.com/beipo-ai/NorthCUA/tree/fb5f9e2725c7cfe268fa0c2dc40f44cc132c12f4\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision fb5f9e2725c7cfe268fa0c2dc40f44cc132c12f4\">fb5f9e2 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Carry out one user computer-use task through observed Desktop/Web state and model-chosen actions. - Disturbance / variety regulated: Unknown application screens, changed DOM/state, unexpected tool responses, context growth, unsatisfied task conditions and execution interruptions. - Decisive decision or feedback right: Choose next computer-use/tool action or finish based on observed state and returned tool results. - Decision owner: Configured agent model operating in the first-party Desktop/Web round executor; external inference service supplies model computation but does not implement the NorthCUA task loop. - Supporting / enforcement mechanisms: NexAU-compatible model adapter, typed tool contracts, context/image window, working notes, action backend, controller/device bridge, step budgets and persisted history. - Closure path: User request → contextual observation → model step/action choice → constrained tool execution → new screenshot/DOM/tool result and notes → subsequent model step or terminal result. - Boundary reachability: The documented local Web/Desktop CLI and remote task modes instantiate this actor loop using bundled AgentKit specs and first-party tool dispatch; no test-only harness or adjacent research agent is needed. - Why this is / is not agent-owned: The model selects substantive environment actions after seeing observations. Tool schemas, transport, budget and safety gates constrain or carry this discretion rather than select it. - Evidence: Web agent specification, Desktop step executor, runtime architecture. - Basis: explicit + structural. - Confidence: high for the first-party model/tool loop; no live hosted-provider success claim. - Caveats: S1 depends on configured model/device/backend availability, and the assessment does not measure task efficacy.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: Attenuate interference between distinct simultaneously admitted batch task attempts, especially duplicate execution, resource oversubscription and accidental state reuse. - Disturbance / variety regulated: Concurrent attempts may claim the same task, worker/device capacity or prepared environment after restarts, timeouts and parallel preparation. - Decisive decision or feedback right: Select or revise which attempt can claim a lease and when backpressured capacity may admit subsequent tasks; a higher-level autonomous coordination policy would have to be composed to own the discretion. - Decision owner: First-party deterministic scheduler, leases and persisted rules select immediate admission based on human/developer-provided limits; there is no demonstrated autonomous agent choosing inter-task coordination policy. - Supporting / enforcement mechanisms: SQLite task claim/heartbeat, attempt identity, task-scoped sandbox/device lease, backpressure samples, single-use prepared reservation and reconciliation. - Closure path: Contending batch attempts → exclusive task/lease claim and controller-pressure check → one attempt proceeds, conflicting contenders wait or reconcile → subsequent tasks claim only released/eligible capacity. - Boundary reachability: Batch mode ships these scheduler/lease components and documented resume semantics; unlike a hypothetical generic queue, the code specifically handles simultaneous task claims and attempt reuse. - Why this is / is not agent-owned: Concrete inter-S1 conflict attenuation exists, but its decisive runtime rule is deterministic; a first-party S2-specific constructor path is exposed without a shipped model-owned policy adjustment loop. - Distinct S1 units: Independently running Desktop/Web task attempts with their own task goals, environments and actor loops under a single batch. - Inter-S1 disturbance: Duplicate task submissions or competing sandbox/device admissions and reused application state when attempts overlap or a runner resumes. - Attenuating coordination relation: Unique task/attempt claims and task-scoped leases, bounded concurrency, backpressure gating and selected retry/reconcile rules. - Feedback into subsequent S1 behaviour: Denied/late claims do not start duplicate actor operations; capacity availability and persisted task status determine later submission and resume. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: The coordination enforces a named cross-attempt collision and resource contention invariant and feeds a concrete admission/withholding result into subsequent distinct task attempts. - Evidence: batch scheduler, lease coordinator, backpressure gate, batch recovery documentation. - Basis: structural. - Confidence: medium-high for an actual inter-attempt coordination path, medium for constructor classification. - Caveats: The batch is optional; an individual local run has no distinct S2 peer set. Deterministic conflict avoidance cannot be upgraded to S2=A without autonomous coordination discretion.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: Whole-batch current commitments and running capacity can be supervised by a legitimate operator who controls admission, pause, cancellation, drain and selected retries. - Disturbance / variety regulated: Failed or uncertain attempts, exhausted retry budgets, workload pressure, controller interruptions and cleanup problems across a batch. - Decisive decision or feedback right: View current aggregate task statuses and choose to stop new admissions, cancel current work, drain running tasks, resume or authorize specific failed-task retries. - Decision owner: The first-party mode&#39;s human batch operator. The scheduler and SQLite state apply that returned decision; no independent AI whole-batch manager is shipped. - Supporting / enforcement mechanisms: Status/report CLI, persisted control flags and task states, pause/drain/cancel handlers, selected-retry plan validation and scheduler poller. - Closure path: Operator reviews whole-batch status/report → invokes pause/drain/cancel or bounded selected retry/resume → persistent flags/attempt ceilings are read by the live scheduler → current/new task admissions and execution change. - Boundary reachability: The documented northcua batch status|report|pause|drain|cancel|resume commands and scheduler&#39;s control-flag poller form a usable first-party operator mode over the same persisted batch. - Why this is / is not agent-owned: This is an operationally returned parent mode (P), not automatic agent S3; deterministic capacity thresholds and external operator actions do not supply autonomous S3=A or C by themselves. - Whole-system current view: Persisted all-task states and report/failure breakdown across one identified batch, including attempts and evaluation statuses. - Current-control decision scope: Stop or resume new admissions, cancel active work, drain committed tasks and select permitted retries for failed tasks, affecting whole-batch present commitments. - Evidence: batch operator commands, CLI branch handling, control-flag scheduler, selected retry plan. - Basis: explicit + structural. - Confidence: medium; owner/control return is directly coded, but no actual operator run was reproduced in this assessment. - Caveats: Parent governance is only at a single batch&#39;s current-operations recursion, not at the OSS project&#39;s policy/identity recursion. This finding does not classify arbitrary status dashboards as S3.\">P</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: A separate evaluator agent challenges actor completion against independently gathered artifact and optionally live application reality. - Disturbance / variety regulated: Agent self-report may disagree with task requirements, unsaved application state, missing artifacts or unseen outcome failures. - Decisive decision or feedback right: Select relevant raw/recorded evidence and optional live probes, judge requirements and submit a structured success/failure report distinct from actor termination. - Decision owner: The separately instantiated first-party model-driven evaluator, through its own tool-selection and final-report loop; not the actor, trace writer or deterministic batch status projector. - Supporting / enforcement mechanisms: Evidence manifest, read-only artifact and live probe tools, bounded evaluator step execution, report schema, fail-open/fail-closed configuration and batch result projection. - Closure path: Actor completion → independent artifact/live evidence collection → evaluator model verdict in finalreport → recorded outcome distinct from actor claim → batch task becomes success/failure/pending and controls downstream retry/reporting decisions. - Boundary reachability: Shipped local/remote Web/Desktop evaluator modes can be enabled in app configuration or CLI, and the Web evaluator runs before releasing the actor&#39;s original browser session. A direct live probe is conditional on explicit permission; the artifact-evidence route remains independently wired. - Why this is / is not agent-owned: The evaluator chooses direct evidence inspection and a task-grounded judgment in its own model/tool loop; its report changes terminal status. Deterministic tooling does not make that independent audit judgment. - Claim being audited: Whether the actor actually satisfied the user&#39;s task despite its own reported completion. - Ordinary reporting path: Actor terminal result, its model/tool traces, screenshots and action outputs. - Complementary access path: Separate evaluator&#39;s evidence selection and tool access to saved artifacts plus, when enabled, fresh DOM/screenshot or allowed device read-only probes against the original live session. - Independence boundary: The evaluator executes in a separate model-round/runtime and has evidence/probe tools unavailable to ordinary self-report; it is still a first-party evaluation path, not an externally independent scientific audit or proof of blind reviewer independence. - Who acts on findings: Batch status projection treats a present negative verdict as failure, while operator/retry flow may admit a subsequent attempt; no claim that the same actor is automatically corrected before finalization. - Evidence: evaluator loop, Web evaluator service, read-only probe contracts, terminal projection, evaluation modes. - Basis: explicit + structural. - Confidence: medium-high for independently wired model audit and returned verdict, not for real-world judge accuracy. - Caveats: Evaluation may be disabled or fail open; live probes require permission and original session availability; a status verdict affects subsequent batch handling rather than guaranteeing a corrective rerun. No actual hosted model, external evaluator or empirical accuracy study was executed for this assessment.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No shipped S4-specific prospective external-environment model and adaptation-option decision returning to present organizational capability. - Disturbance / variety regulated: Changes in apps/sites, task complexity and model quality are seen by current actor/evaluator, but not separately explored as future environment adaptation at the batch/harness recursion. - Decisive decision or feedback right: Generate future-facing capability/policy adaptation options from external distinctions and negotiate them with current operational control. - Decision owner: Project developers/operators may separately plan upgrades; actor plans current tasks, evaluator judges completed work. - Supporting / enforcement mechanisms: Working notes, image/context compaction, feedback artifacts, model/provider configuration, benchmark and research documentation. - Closure path: Task observations and evaluator reports feed current run/batch status, not a first-party outside-and-then option/implementation return loop. - Why this is / is not agent-owned: Task planning, context memory, runtime retries and post-run quality reporting are not themselves prospective adaptation judgments. - Evidence: system tour, context mechanisms, batch lifecycle. - Basis: structural. - Confidence: medium-high within the reviewed distribution. - Caveats: Research and model upgrades can support future work outside this runtime boundary.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No system-level identity or ultimate-policy resolution channel with a legitimate deciding owner and returned binding decision is shipped for the assessed task/batch organization. - Disturbance / variety regulated: Risky computer actions, provider/device access, evaluation-probe mutability and cost/time limits are bounded by operator-set configuration and tool controls. - Decisive decision or feedback right: Adjudicate contested identity/purpose/ultimate-policy matters and return binding changed policy to the running organization. - Decision owner: Users/developers choose static configuration and external provider access; no first-party S5 decision actor or parent appeal path is established for such matters. - Supporting / enforcement mechanisms: Read-only evaluator probes by default, explicit mutating-tool opt-in, sandbox capabilities, model/task budgets, run authorization and cancellation. - Closure path: Current operator configuration → enforcement of permitted tools/budgets, with no identity-level proposal → parent authority → decision → changed operation loop. - Why this is / is not agent-owned: Ordinary permission and task cancellation choices are not ultimate-policy decisions, and no shipped independent policy/identity deliberation return is identified. - Evidence: evaluation configuration, batch configuration, architecture. - Basis: structural. - Confidence: medium-high at assessed operation/batch boundary. - Caveats: Project maintainers naturally retain licensing/release governance, but that adjacent project-level authority cannot be silently credited as runtime S5.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/0ad99b51aef44dd4a35185e7ecf73717a6d29557/assessments/no/northcua.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 0ad99b51aef44dd4a35185e7ecf73717a6d29557\">0ad99b5 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-05T20:13:32+03:00\"><th scope=\"row\"><a href=\"https://github.com/halayhq/halay\" target=\"_blank\" rel=\"noopener\">halay</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/halayhq/halay/tree/49bccfcb75e805b7ab55bb40c92a109dcdc62c24\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 49bccfcb75e805b7ab55bb40c92a109dcdc62c24\">49bccfc &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: Distinct user-task agents operate in their assigned project directories through the launched configured CLI. - Disturbance / variety regulated: Changing user requests, project state and subprocess/tool feedback delivered to each CLI session. - Decisive decision or feedback right: Each running model-backed CLI agent chooses task actions and next turns, while halay controls the first-party spawning, routing, replies and child communication interface. - Decision owner: Individual CLI-backed model task actor, through halay&#39;s installed multi-agent composition; not Node HTTP request routing alone. - Supporting / enforcement mechanisms: Backends, per-agent cwd/account/model, MCP swarm tools, event stream, permissions and optional worktrees. - Closure path: User/conductor task→halay launches addressed CLI agent→upstream engine acts in workspace→result/status returns via halay→model continues, receives follow-up or returns result. - Boundary reachability: src/server.js launches supported CLI processes and src/swarm-mcp.js exposes actionable tools; this requires one external CLI installed and authenticated, and does not credit its underlying internal tool loop as a first-party implementation. - Why this is / is not agent-owned: Real CLI-backed models have discretion over work; the first-party control plane enables and observes their running roles. The launcher alone would not be autonomous. - Evidence: spawn and task lifecycle, backends, swarm tools. - Basis: Supported executable agent-CLI composition and returned operational state, not claimed first-party model internals. - Confidence: Medium-high for first-party runtime integration, not upstream vendor correctness. - Caveats: The prerequisite external CLI supplies cognition, local tool semantics and vendor behavior; absent a configured backend, halay is an idle control plane.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: No separately demonstrated autonomous attenuation of an observed conflict among the multiple operating child units. - Disturbance / variety regulated: Shared-workspace collisions and competing task dependencies are plausible; the default task DAG orders work but is authored and assigned as a workflow, not measured inter-S1 contention. - Decisive decision or feedback right: First-party dependency gate rejects blocked starts; conductor can manually/model-select routing as S3 rather than independent S2 balancing. - Decision owner: User/conductor for assignments, deterministic task dependency guard for eligibility. - Supporting / enforcement mechanisms: Task graph dependson, worktrees, agent message bus, parent-child scoped tools and queues. - Closure path: Task dependency→ready/waiting/blocked gate or manual assignment; messages travel between actors, but no installed contention sensing→S2 arbitration→revised peer behavior loop. - Why this is / is not agent-owned: Tool messages, worktree isolation and static dependency checks are valuable coordination infrastructure without evidence of a specific separately owned S2 regulator. - Evidence: task dependency/agent management, swarm tool interface. - Basis: Bounded absence after testing strongest task-DAG and peer-messaging candidates. - Confidence: Medium-high. - Caveats: A conductor can respond to a user-observed conflict, but no distinct routine S2 feedback mandate was found in the shipped setup.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A - Function: Shipped model-driven conductor supervises the present agent fleet and allocates/revises task commitments and capacity. - Whole-system current view: Conductor&#39;s listagents, task listing, status/attention, child-result notifications and account availability expose the bounded installed fleet and current work backlog, rather than a single worker&#39;s perspective. - Current-control decision scope: Conductor can choose and revise work-to-child allocation, active agent count/model/folder, follow-up task instructions and interruption in response to observed fleet state. - Disturbance / variety regulated: Concurrent user requests across projects, idle/busy/blocked children, failed tasks, approval pauses, delayed results and current model/account capacity. - Decisive decision or feedback right: Conductor chooses whether to create or reuse an agent, what folder/model/account to assign, when to message or interrupt it and how to react to its returned result/status. - Decision owner: Conductor model running with the bundled role prompt and privileged first-party swarm MCP rights; runtime enforces access scopes and completion notifications. - Supporting / enforcement mechanisms: listagents, startagent, sendmessage, readagent, task assignment, stop/interrupt, child-finish notifications, persistent fleet state and task dependency gates. - Closure path: User&#39;s multi-project goal→conductor lists fleet/task state→selects agent and assignment→agent acts→halay notifies its completion/error/block→conductor revises instructions, assignments or informs user. - Boundary reachability: A shipped Swarm chat has its own conductor role and tool permissions; unlike a passive dashboard it can model-select concrete task allocation from returned runtime state. - Why this is / is not agent-owned: The first-party conductor prompt gives the model an operational portfolio mandate and action rights; subprocess state and database enforcement support rather than replace its choices. - Evidence: conductor mandate, scoped MCP actions, fleet/task state and wakeup, notification format. - Basis: Reachable first-party conductor perception→discretionary allocation/revision→child-action→status feedback over a bounded fleet. - Confidence: High for installed mandate and capability, not measured real fleet performance. - Caveats: The conductor&#39;s decision model runs via a required external CLI and may fail to act on feedback; human controls, context budgets and per-child permissions constrain it.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3* / direct audit: - State: — - Function: No independent alternate evidence path produces an audit verdict returned to conductor beyond ordinary agent and tool reports. - Disturbance / variety regulated: False child completion claims and unsafe changes could be reviewed by humans; no separate installed auditing reviewer independently samples operational reality. - Decisive decision or feedback right: Conductor can read child transcript, summaries and git status, but this is ordinary supervision; approvals are chosen by the human. - Decision owner: Conductor for monitoring and operator for approvals; no complementary auditor with independent judgment/return authority. - Supporting / enforcement mechanisms: Agent transcript, worktree state, browser UI, status notifications, reviewable git changes and authentication. - Closure path: Child events→conductor/UI; no independent artifact sampling/replay→adversarial audit finding→corrective S3 loop in standard distribution. - Why this is / is not agent-owned: A separate transcript reader does not gain a distinct independent observational channel, and the human may optionally review but is outside first-party installed audit. - Evidence: swarm read/status, event handling. - Basis: Bounded absence review of strongest transcript/worktree evidence paths. - Confidence: Medium-high. - Caveats: External CLI vendors or human code review may supply external auditors, not credited to halay by default.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: No continuous prospective environment analysis selects future capability/organizational changes for this fleet. - Disturbance / variety regulated: New CLI backends, future user work, schedule timing, model prices and capacity changes. - Decisive decision or feedback right: Operator configures accounts/backends and schedules; conductor handles current task choices and user-described future jobs. - Decision owner: Human operator for product/organizational evolution, conductor model for present tasks. - Supporting / enforcement mechanisms: Backend discovery, scheduled/recurring tasks, durable bots, peer configuration and model selection. - Closure path: User configuration/schedule→current or timed execution; no outside environmental forecast→strategic option selection→negotiation with current S3 and adopted future operating rule. - Why this is / is not agent-owned: Scheduled execution and selectable backends are operational capacity, not autonomous anticipation of changing external circumstances. - Evidence: server and task schedule, conductor instructions, bots. - Basis: Bounded absence review including strongest persistent/scheduled mode. - Confidence: High. - Caveats: Conductor can be asked to research future changes as a one-off S1 work item; no permanent S4 function follows.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: No distinct legitimate ultimate identity-policy role owns and closes an organizational charter/mandate. - Disturbance / variety regulated: Privileged agent management, resource/cost limits, malicious agents, user identity/authentication and permission escalation. - Decisive decision or feedback right: Authenticated human owner sets controls; static role access enforces conductor versus child scope, and the user decides tool approvals. - Decision owner: Operator for legitimate ultimate constraints, deterministic auth/MCP guard for enforcement. - Supporting / enforcement mechanisms: Passkeys, per-agent bearer tokens, parent ownership checks, approval mode, model/account boundaries and persistent configuration. - Closure path: Operator setting or approval→guarded API behavior; no autonomous or parent-assisted identity-policy deliberation and returned authoritative mandate to S3/S4. - Why this is / is not agent-owned: Strong security and an exclusive conductor role are not sufficient for an independent governance legitimacy cycle. - Evidence: auth/access, MCP scoping, server. - Basis: Bounded absence after screening legitimate operator policy and role privilege paths. - Confidence: High. - Caveats: A human-led institution could govern an installed halay fleet; it is not a supplied self-governing S5 actor.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/0d074c28204362cf5ef61e4df5c16812954ee014/assessments/ha/halay.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 0d074c28204362cf5ef61e4df5c16812954ee014\">0d074c2 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-02T17:08:05+03:00\"><th scope=\"row\"><a href=\"https://github.com/lose4578/Auriga\" target=\"_blank\" rel=\"noopener\">Auriga</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-02\">2026-11-02</time></td><td class=\"review-ref\"><a href=\"https://github.com/lose4578/Auriga/tree/3e1be75e186e49f8c268fd5fc6c08427f99254ce\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 3e1be75e186e49f8c268fd5fc6c08427f99254ce\">3e1be75 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: pursue robot-manipulation goals through visual observation, task planning, multi-stage preview/execution, measured action feedback and recovery. - Disturbance / variety regulated: changing object/robot geometry, failed or partial grasps, occlusion, movement slips, constrained arm trajectories and uncertain action completion. - Decisive decision or feedback right: choose the next physical task action, observation, program, trajectory revision or recovery in light of returned evidence. - Decision owner: primary model-driven Codex actor (named Astra in optional verification documentation), with action authority mediated by the Harness. - Supporting / enforcement mechanisms: action identity and current-observation checks, native motion planner, gripper guards, single action writer, program review broker, action ledger, wall/budget supervision and the physical simulator. - Closure path: Codex task/plan → robotobserve and robotaction preview → model selects execute → Harness.execute native worker → measured receipt/images/stop reason → model adjusts or terminates episode. - Boundary reachability: normal gateway creates the Codex session and Harness, registers robotaction and connects execution to native RoboDojo worker. The model/tool loop is shipped with documented flags, not merely a benchmark test. - Why this is / is not agent-owned: static robot safety gates do not select a new manipulation strategy; the actor model makes the task-level decisions even when a hard guard prevents unsafe execution. - Evidence: README execution loop, Harness, model-led operation. - Basis: structural -\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no distinct conflict-specific inter-S1 coordination and return is established in the supported robot actor organization. - Disturbance / variety regulated: dual-arm trajectory interference and concurrent program/native action requests are real actuator/resource hazards but not conflicts among distinct autonomous S1 units. - Decisive decision or feedback right: arbitrate independent agent commitments and return a coordination resolution; not evidenced. - Decision owner: one actor plans both arms; deterministic Harness serializes physical actions and rejects stale plans, rather than an S2 coordination owner regulating competing agents. - Supporting / enforcement mechanisms: stage-order dependencies, dual-arm path preview, active-writer exclusivity, plan revision, program broker approval and stop gates. - Closure path: native constraints and the primary actor can alter a manipulation task, but no separate inter-S1 interference-resolution result is fed into distinct operational agents. - Why this is / is not agent-owned: two robot arms are not independent goal-directed S1 cells; an optional evidence agent audits a claim but does not compete for physical task execution. - Evidence: unified actions, Harness action writer, program review. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no independent whole-organization current-control authority over a population of operational S1 commitments is demonstrated. - Disturbance / variety regulated: native action budget, simulator step accounting, active action conflicts, unknown stop confirmation, model transport failures and episode wall limits. - Decisive decision or feedback right: select systemic allocation/priority/commitment intervention across distinct operations; absent beyond the single robot episode&#39;s work plan. - Decision owner: primary actor owns task strategy; Harness enforces state/timeout/cost constraints; operator defines task/benchmark configuration. - Supporting / enforcement mechanisms: supervision.waitturn, action gate, per-action budget, program source grants, GPU resource checks and status/feedback records. - Closure path: failures can stop one episode or prompt its actor to try another action, not a separate whole-current S3 decision that regulates multiple autonomous units. - Why this is / is not agent-owned: counters, stop gates and request retry policy are enforcement; removing a hypothetical S3 model leaves them intact. - Evidence: runtime supervision, Harness, model-led operation. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Claim being audited: the primary robot actor&#39;s local claim that a selected grasp/lift/transfer/place/release or retreat phase achieved its expected visible result, as distinct from a native worker&#39;s narrower completed execution receipt. - Ordinary reporting path: Harness.execute returns a native action receipt and current measured observation to the primary actor, which can then report success on the strength of its own readings; a tool response alone does not prove object retention or task completion. - Complementary access path: the separately launched Sol reviewer is given the raw linked BEFORE/AFTER permitted RGB images, measured robot state, immutable action IDs/receipts and the actor&#39;s intended outcome as a hypothesis; it checks visual identity/relation independently and returns a structured met/notmet/uncertain verdict with gaps. - Independence boundary: CodexEvidenceAgent creates a fresh ephemeral thread, empty workspace and isolated home, disables memories/tools/hooks, and rejects observed helper tool activity; it is not forked from the acting Codex history and cannot issue motion commands. The actor chooses checkpoint and evidence, limiting scope but not transferring visual judgment to the actor. - Who acts on findings: the primary Astra actor receives visionreview results in its ordinary tool stream and is instructed to resolve unmet/uncertain evidence with fresh observations or changed recovery; the reviewer itself cannot execute or compel a trajectory and the operating loop retains physical action ownership. - Function: provide an independent, evidence-limited second opinion on a manipulation operation&#39;s claimed visible outcome and send discrepancies or uncertainty back to the acting agent. - Disturbance / variety regulated: optimistic success interpretations of completed motion receipts, wrong target identity, occlusion, unsupported grasp/placement/release claims and partial execution. - Decisive decision or feedback right: judge met, notmet or uncertain for a claimed phase by comparing independent before/after RGB, execution receipts and measured robot state, and specify evidence gaps/recovery feedback. - Decision owner: separate fresh gpt-6.1-sol evidence agent; primary Astra remains owner of the subsequent physical action and the operator decides whether to enable this configuration. - Supporting / enforcement mechanisms: deterministic provenance and schema checks, isolated fresh home/thread, suppressed tools/memory, payload source hashes, shared model budget, exact model assertion and unsupported-positive veto in constrainanswer. - Closure path: actor selects meaningful checkpoint and invokes visionreview(evidencemode=&#39;operation&#39;) → fresh Sol independently examines linked images/receipts and issues bounded verdict and follow-up → tool response returns to the primary actor&#39;s Codex turn → actor instructed to resolve uncertainty or choose a changed recovery before later motions. The auditor never executes robot actions. - Boundary reachability: features.visualreviewmodel=&#39;gpt-6.1-sol&#39; is a documented supported config; the actual Workbench instantiates VisualReviewer(CodexEvidenceAgent(session)), the runtime tool handler dispatches it and returns the structured assessment to the ordinary actor context. Default null mode has no S3 helper; positive vector reflects the first-party enabled operating mode, not default execution. - Why this is / is not agent-owned: the fresh model provides the discretionary visual evidence judgment; deterministic validation limits unsupported assertions but cannot itself interpret ambiguous target retention/phase outcome. Actor authority to choose recovery is distinct from auditor judgment ownership. - Evidence: mode and return contract, Workbench construction, fresh agent isolation, review judgment, actor recovery instructions, tool handler. - Basis: structural - Confidence: medium - Caveats: actor chooses evidence/request and need not obey a fixed compulsory verification phase sequence; this is a first-party supported optional independent second-opinion loop, not privileged simulator-ground-truth audit or guaranteed physical correction. No real provider/robot verification was executed here.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no separate externally prospective adaptation process with authorized whole-runtime capability-choice and return is demonstrated. - Disturbance / variety regulated: novel object geometries, repeated failed grasps, changing camera viewpoints, different robot scenes and future task transfer. - Decisive decision or feedback right: change organizational operating capability based on prospective environmental alternatives; not evidenced at the assessed one-episode recursion. - Decision owner: primary model adapts task actions in the current scene; developers/operators configure perception services, model and robot plugins. - Supporting / enforcement mechanisms: adaptiveactioncheckpoint failure reminders, observation memory, trajectory cost previews, program synthesis and optional external perception. - Closure path: measured failures can prompt an immediate alternate grasp, viewpoint or trajectory within one task; no distinct environment/future analysis → approved organization-wide capability adaptation → feedback loop is implemented. - Why this is / is not agent-owned: adaptive recovery within one operating episode is S1 learning/action selection, not automatically S4 strategic adaptation. - Evidence: checkpoint helper, model-led recovery, unified actions/memory. - Basis: structural -\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no ultimate organizational policy/identity arbitration with legitimate authoritative return is implemented inside the robot episode. - Disturbance / variety regulated: robot safety boundaries, model permissions, execution modes, privileged task truth, tool grants and physical stop decisions. - Decisive decision or feedback right: adjudicate identity-level commitments and revise binding policy for the whole; not shown beyond fixed configuration and task controls. - Decision owner: developer/operator specifies guardrails and modes; deterministic Harness enforces validation; primary actor decides ordinary manipulation steps within those bounds. - Supporting / enforcement mechanisms: actor observation redaction, action schema and state locks, program grants, model call budget and sandbox controls. - Closure path: individual actions are admitted/rejected against predefined rules, but no policy-level dispute → qualified authority → ultimate decision → new identity-governing operating rule is shipped. - Why this is / is not agent-owned: the model may choose a risky trajectory and receive advisory data, but it does not own the system&#39;s ultimate identity or change invariant control policy. - Evidence: action gate, actor information boundary, model-led operation. - Basis: structural -\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/ec6167d00afe015e5c030fd19139e421de731e13/assessments/au/auriga.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit ec6167d00afe015e5c030fd19139e421de731e13\">ec6167d &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-11-05T17:57:28+03:00\"><th scope=\"row\"><a href=\"https://github.com/mihazs/agent-harness-lab\" target=\"_blank\" rel=\"noopener\">Agent Harness Lab</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/mihazs/agent-harness-lab/tree/1b165594818bab9f92605fb4bd5ec0c6f943c2fc\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 1b165594818bab9f92605fb4bd5ec0c6f943c2fc\">1b16559 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: investigate bounded harness defects and generate an executable candidate instruction/skill change against project evidence. - Disturbance / variety regulated: unknown agent failure mechanisms, contradictory observations, ineffective instructions, regressions and source-context gaps. - Decisive decision or feedback right: the proposer model chooses which supported mechanism to address and what candidate file edits to stage; baseline/candidate model task executors choose actions under identical frozen tasks and runtime settings. - Decision owner: selected Codex/Claude/Responses model-backed proposer and task roles in explicitly invoked improve mode; first-party controller scopes and executes them. - Supporting / enforcement mechanisms: project-local snapshots and path allowlists, model role prompts, source/analysis receipts, artifact hashes, shared trial/time ceiling, frozen candidate, paired executors and evaluation feedback. - Closure path: collect bounded evidence → proposer model selects candidate → change is frozen → baseline and candidate agent trials execute → observed failures/regressions feed the bounded refinement or final no-change/recommendation. - Boundary reachability: workflow.py invokes native/Responses role runner in preparation and task phases; ahl improve is the documented CLI entry, provided runtime availability and permissions. - Why this is / is not agent-owned: proposer decides semantic repair hypotheses and actual candidate contents, not just a deterministic suggested text; analyze, static classifiers and test bookkeeping alone would be constructors, not S1 A. - Evidence: proposer dispatch and trial flow, controlled role preparation, documented modes. - Basis: pinned first-party execution code and runtime contract; not a live paid Codex/Claude experiment here. - Confidence: high that model-backed roles are shipped, medium for real-world repair quality. - Caveats: no model calls in analyze or offline diagnostics; no general automatic promotion implied by successful paired tasks.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no separately established inter-S1 reciprocal conflict-attenuation loop beyond task role isolation and experiment scheduling at the defined single-run boundary. - Disturbance / variety regulated: a proposer could contaminate evaluator inputs or a concurrent improvement run could alter the same project, but AHL prevents those situations by frozen views/locks rather than demonstrated feedback among independently operating S1 units. - Decisive decision or feedback right: controller grants separate role paths, budgets, frozen snapshots and project locks; a stale or leaked input blocks the whole evaluation. - Decision owner: deterministic custody/permission controller, without cross-worker conflict-specific negotiation or corrective return to both S1 cells. - Supporting / enforcement mechanisms: role-scoped views, frozen task banks and hashes, project lock, candidate/baseline isolation, source-drift checks, sequential trial orchestration. - Closure path: potential cross-role contamination is prevented or detected; invalid runs stop or require intervention. This is evaluation integrity, not evidenced coordination of independent operational commitments. - Boundary reachability: role views, frozen candidate and validation are shipped; a separate correction negotiation between proposer and evaluator is not. - Why this is / is not agent-owned: distinct fresh roles, sequential stages and file isolation are important safeguards, but not enough to infer VSM S2 without a concrete disturbance-feedback relation returning to affected S1 units. - Evidence: role construction and separation, controlled execution boundaries, preflight/custody policy. - Basis: bounded negative review of multi-role experiment/custody paths. - Confidence: medium-high for this recursion. - Caveats: a future multi-project adaptation fleet could implement true S2; that is outside this single-project run.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3 / regulation: - State: C(P) - Function: regulate the active run&#39;s preparation/evaluation roles, resource budget, candidate eligibility, current evidence and terminal disposition, with user-owned runtime/scope initiation. - Disturbance / variety regulated: budget exhaustion, changed source files, invalid evaluator controls, failing task bank, unavailable authentication, partial runs and repeated monitoring without new evidence. - Decisive decision or feedback right: controller freezes/validates candidate and grader inputs, schedules tests/refinement, rejects a candidate or emits recommendations; human owner authorizes project, chosen runtime, scope and any later behavioral adoption. - Decision owner: deterministic workflow.py and promotion prerequisites (C), with human operator (P) initiating and deciding outside-CLI adoption. Controller does not quietly grant itself publication rights. - Supporting / enforcement mechanisms: project locks, shared 45-minute/24-role defaults, checksums, state receipts, role budgets, graded trial coverage, early fail-closed exits, optional monitor checkpoints. - Closure path: current evidence and role result → controller authorizes next preparation/test/stop or reports unsupported → stored checkpoint/receipt constrains the next agent dispatch. - Boundary reachability: ahl improve and ahl watch use these live controller functions; watch is foreground and must be explicitly started. - Why this is / is not agent-owned: current-run scheduling/disposition is rule-based despite model roles doing task work; real human controls authenticated invocation and reviewed candidate adoption. - Whole-system current view: baseline/candidate hashes, source identity, proposer/evaluator states, task bank coverage, model calls, time/trial remaining, results and previous monitor checkpoints. - Current-control decision scope: allow/deny a role run, protect frozen inputs, retry once, stop on invalid evidence, write final review/recommendation and watch restart suppression. - Evidence: controller loop, invocation preflight, monitoring mode. - Basis: first-party deterministic role/state controller. - Confidence: high in structural control rights; actual credentialed runs not repeated here. - Caveats: human adoption beyond CLI and real trusted production integration are not claimed as observed automatic completion.\">C(P)</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: a separately prompted evaluator-author agent constructs tests/graders from baseline/source evidence while deliberately blind to the candidate, and the controller executes those frozen evaluators to challenge the proposer&#39;s claimed improvement. - Disturbance / variety regulated: proposer self-praise, overfit instruction rewrites, candidate-specific tests, evaluator leakage and differences that disappear on held-out/regression cases. - Decisive decision or feedback right: evaluator-author model independently chooses test cases and grader construction within the baseline evidence and broken/partial/complete control contract; frozen graders then measure actual paired task outputs and can cause rejection or bounded refinement. - Decision owner: separate fresh model-backed evaluator-author role owns substantive test design; deterministic comparison controller enforces controls and verdict/disposition. - Supporting / enforcement mechanisms: separate role workspace/views, baseline-only source context, withheld candidate and held-out inputs, grader self-tests, manifest freezing, task result artifacts, same-runtime paired trials and custody checks. - Closure path: proposer freezes candidate/claim → independently scoped author designs tests without seeing patch → controls/graders are frozen → baseline/candidate execute → actual result comparison rejects/permits refinement or emits review recommendation. - Boundary reachability: workflow.py constructs a separate evaluator session in native mode or construction.author/controlled role access, and validates a manifest before paired trials. No optional uninstalled reviewer service is required beyond the chosen agent runtime. - Why this is / is not agent-owned: deciding what independent probes should measure involves a different model context, not simply running a copy of the proposer&#39;s test; the final grader/veto itself is deterministic, so this is not automatically a certified independent human scientific audit. - Claim being audited: a proposed harness instruction/skill edit improves required task outcomes without regression under comparable inputs. - Ordinary reporting path: proposer mechanisms, candidate diff, self-declared proposal.json and any development trial feedback. - Complementary access path: evaluator author receives baseline/source/analysis without candidate patch, builds unrelated executable tasks and graders, and the controller examines fresh baseline/candidate task artifacts. - Independence boundary: roles are separately scoped and patch-blind by construction, but cooperative Codex/Claude runtime/hook behavior and model provider isolation are not proven adversarial security; some source metadata is shared. - Who acts on findings: controller rejects/refines/recommends; human decides any behavioral adoption. No claim of certified unconditional promotion. - Evidence: independent evaluation-construction prompt and calls, role-specific controlled author, frozen task method. - Basis: explicit shipped two-role model construction plus executable artifact feedback, not observed scientific effect size. - Confidence: medium-high for independent input view and actual verdict path, medium for model quality and native role isolation. - Caveats: “fresh session” alone is not a proof of full root independence or test correctness; graders need explicit self-tests and absence of leakage.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no completed behavioral adoption return turning evaluated future-harness candidates into active project operating capability under the shipped CLI&#39;s general workflow. - Disturbance / variety regulated: evolving task types and systematic future agent behavior might warrant new harness instructions and skills. - Decisive decision or feedback right: proposer can forecast candidate effects and evaluation compares development/regression/held-out tasks, but improve deliberately returns a review recommendation instead of applying behavioral changes; the human may later edit active files separately. - Decision owner: user/project outside the CLI owns actual behavioral promotion; no first-party general S4 decision-to-adoption loop has authority. - Supporting / enforcement mechanisms: retrospective analysis, selected candidate proposals, prospective task banks, held-out controls, promotion prerequisites and fail-closed recommendation status. - Closure path: candidate → prospective paired task evidence → review recommendation; missing final behavioral activation in the same supported controller means the full outside-and-then capability return is unclosed. - Why this is / is not agent-owned: creating and evaluating future options is substantial S4-adjacent intelligence but cannot be scored as completed S4 when the proposed capability is explicitly not adopted. Narrow structural BOM repair is not general behavioral S4. - Evidence: README no auto-adoption, promotion policy recommendation-only, one-call narrow repair. - Basis: explicit runtime/README negative authority and supported-mode examination. - Confidence: high for CLI&#39;s deliberate blocked behavioral return; a manual fallback may differ under explicit user authority. - Caveats: installed harness-self-improvement skill describes assisted evaluation/editing; without a validated matching runtime/receipt this is not imported as general autonomous promotion into the guarded ahl improve path.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no legitimate whole-project identity/ultimate-purpose adjudication loop evidenced in one harness optimization run. - Disturbance / variety regulated: privacy of traces, scope of external models, credentialed cost, whether an evaluator can be trusted and changes to global instructions are real governance concerns. - Decisive decision or feedback right: invocation permissions and configured scope restrict project files and runtime capabilities, while the user decides model/provider, accepts adoption and can stop the command; none is charter-level identity resolution returned as binding system purpose. - Decision owner: outside user/project authority; controller enforces safety/eligibility preconditions rather than deliberating ultimate purpose. - Supporting / enforcement mechanisms: project path allowlists, no global skills by default, no publication rights, credential-bound external calls, privacy-safe artifacts and explicit fail-closed prerequisites. - Closure path: invalid permission/role scope blocks the run or preserves unmodified files; no first-party identity dispute reaches a higher legitimate policy owner and returns as an ultimate revised charter. - Why this is / is not agent-owned: safety and provenance constraints limit experiments but are not themselves S5 governance. - Evidence: scope and limits, preflight boundaries, promotion authority. - Basis: bounded negative review. - Confidence: medium-high. - Caveats: the human project owner has external policy rights; those are not automatically first-party runtime S5(P).\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/19d30e2238e1d50e87e240bcf67ab7b02ca7f8f6/assessments/ag/agent-harness-lab.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 19d30e2238e1d50e87e240bcf67ab7b02ca7f8f6\">19d30e2 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"0\" data-assessment-at=\"2026-11-01T15:08:00+03:00\"><th scope=\"row\"><a href=\"https://github.com/ZJUZhiyuCai/bread-companion\" target=\"_blank\" rel=\"noopener\">Bread Companion</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>0</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-01\">2026-11-01</time></td><td class=\"review-ref\"><a href=\"https://github.com/ZJUZhiyuCai/bread-companion/tree/058ad153e27bd6470a7e5ef4cab778a93d659a6d\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 058ad153e27bd6470a7e5ef4cab778a93d659a6d\">058ad15 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: autonomous bounded conversation and evidence-task transformation. - Disturbance / variety regulated: different user material, missing/conflicting evidence, rejected interpretations and malformed or inappropriate generated candidates. - Decisive decision or feedback right: choose supported findings, wording, draft structure or a practice question; revise after concrete rejection/validation feedback. - Decision owner: the configured real-agent model within the first-party generation/repair loop. - Supporting / enforcement mechanisms: mode prompts, selected source segments, schema/evidence/style validators, two-attempt repair, run IDs and client lifecycle checks. - Closure path: validation errors re-enter a new generator attempt; accepted content becomes current findings/card/practice state, influencing later turns. - Boundary reachability: real-agent.generate implements the provider interface used by the deployed server; BreadController submits a current turn and reducer applies only matching epoch/context results. - Why this is / is not agent-owned: the model determines substantive task content and correction, while the controller enforces validity and human save authority. Fixed UI transitions alone could not produce the same discretionary outcomes. - Evidence: server/providers/real-agent.ts; prompts/agent.ts; domain/evidence.ts; services/bread-controller.ts; domain/reducer.ts. - Basis: structural. - Confidence: high. - Caveats: no general tool-executing autonomy; drafts require user confirmation for persistence. This is not a therapy efficacy or clinical safety claim.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no distinct operational-unit coordination path. - Disturbance / variety regulated: the function-specific disturbance described below is not regulated by a shipped organizational loop. - Decisive decision or feedback right: no function-specific decisive organizational right established. - Decision owner: not established; runtime mechanisms retain their narrower implementation role. - Supporting / enforcement mechanisms: the inspected task, lifecycle or configuration mechanisms below. - Closure path: no function-specific returned decision into subsequent regulation established. - Why this is / is not agent-owned: These are one conversational work cell&#39;s pipeline/transport stages and revision-consistency controls. No distinct purposeful operational S1 cells with an inter-S1 disturbance/attenuation relation were found. - Evidence: server/providers/real-agent.ts; services/run-controller.ts; services/call-controller.ts; domain/reducer.ts. - Basis: structural. - Confidence: medium. - Caveats: Bounded to the pinned supported distribution; hypothetical downstream extensions are not assessed.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S3 / regulation: - State: — - Function: no whole-current organizational control function established. - Disturbance / variety regulated: the function-specific disturbance described below is not regulated by a shipped organizational loop. - Decisive decision or feedback right: no function-specific decisive organizational right established. - Decision owner: not established; runtime mechanisms retain their narrower implementation role. - Supporting / enforcement mechanisms: the inspected task, lifecycle or configuration mechanisms below. - Closure path: no function-specific returned decision into subsequent regulation established. - Why this is / is not agent-owned: These regulate individual requests, versions, service capacity and task consent. A session view or stop button is not by itself whole-system resource/commitment regulation with a function-specific parent decision loop. - Evidence: services/bread-controller.ts; services/run-controller.ts; domain/reducer.ts; server/limits.ts; server/admission.ts. - Basis: structural. - Confidence: medium. - Caveats: Bounded to the pinned supported distribution; hypothetical downstream extensions are not assessed.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: narrow complementary semantic audit of whether contested analysis reintroduces the user&#39;s denied interpretation. - Disturbance / variety regulated: a candidate can pass schema/verbatim/lexical checks yet paraphrase or recommend the rejected interpretation again. - Decisive decision or feedback right: independently compare actual candidate with user rejection record and judge semantic consistency. - Decision owner: the model in the fresh rejection-review invocation; runtime parses/enforces its verdict. - Supporting / enforcement mechanisms: separate review prompt/request, only candidate/rejection/current user data, bounded audit input, conservative verdict parsing and forced retry/fallback. - Closure path: inconsistent/invalid audit adds REJECTEDINTERPRETATIONREPEATED; generator receives explicit corrective feedback; after a second repeated rejection the product returns quote/unknown fallback rather than display the contested interpretation. - Boundary reachability: RealAgentProvider invokes the separate reviewer only for non-listen analysis with rejectedFindings after normal validation; reducer REJECT and context-builder persist/send that rejection record. - Why this is / is not agent-owned: the independent review call supplies semantic judgment beyond the generator&#39;s candidate and deterministic lexical check; parsing is enforcement, not the owner. No independent provider identity is claimed. - Evidence: server/providers/real-agent.ts; server/providers/rejection-review.ts; domain/reducer.ts; domain/context-builder.ts; domain/evidence.ts. - Basis: structural. - Confidence: medium. - Caveats: same configured model/provider may serve both roles; independence is fresh context and task separation for this narrow consistency claim, not empirical independence from shared model biases. Ordinary chat is unaudited. - Claim being audited: the candidate respects the user&#39;s previously rejected interpretation and its paraphrases. - Ordinary reporting path: generator candidate passes schema/evidence/style and exact-normalized rejection checks. - Complementary access path: fresh semantic comparison of the actual full candidate against persisted user rejection records. - Independence boundary: separate stateless request with dedicated review instructions and no generator hidden reasoning/history; source of correction is user record, not a generator self-report. - Who acts on findings: the provider&#39;s repair loop withholds the candidate, requests revision and eventually substitutes a traceable non-interpretive fallback.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no prospective capability-adaptation loop. - Disturbance / variety regulated: the function-specific disturbance described below is not regulated by a shipped organizational loop. - Decisive decision or feedback right: no function-specific decisive organizational right established. - Decision owner: not established; runtime mechanisms retain their narrower implementation role. - Supporting / enforcement mechanisms: the inspected task, lifecycle or configuration mechanisms below. - Closure path: no function-specific returned decision into subsequent regulation established. - Why this is / is not agent-owned: These adjust current task content, context and service availability. They do not develop future environment/capability options and return an adaptation decision that changes the harness&#39;s present repertoire. Research/benchmark plans are adjacent. - Evidence: domain/context-builder.ts; domain/preferences.ts; server/providers/real-agent.ts; services/bread-controller.ts; docs/product-harness.md. - Basis: structural. - Confidence: medium. - Caveats: Bounded to the pinned supported distribution; hypothetical downstream extensions are not assessed.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no identity or ultimate-policy decision/return path. - Disturbance / variety regulated: the function-specific disturbance described below is not regulated by a shipped organizational loop. - Decisive decision or feedback right: no function-specific decisive organizational right established. - Decision owner: not established; runtime mechanisms retain their narrower implementation role. - Supporting / enforcement mechanisms: the inspected task, lifecycle or configuration mechanisms below. - Closure path: no function-specific returned decision into subsequent regulation established. - Why this is / is not agent-owned: Static identity/permissions and user authority over task/content/save do not supply ultimate-policy arbitration. No identity-level issue is routed to a legitimate ultimate decision owner and returned as a new governing policy. - Evidence: prompts/agent.ts; domain/policy.ts; domain/reducer.ts; services/bread-controller.ts; docs/product-harness.md. - Basis: structural. - Confidence: medium. - Caveats: Bounded to the pinned supported distribution; hypothetical downstream extensions are not assessed.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/8c0178fd561849a1d61ba41f63780227cb755b15/assessments/br/bread-companion.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 8c0178fd561849a1d61ba41f63780227cb755b15\">8c0178f &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-11-04T22:54:17+03:00\"><th scope=\"row\"><a href=\"https://github.com/jirathip-dev/herdsman\" target=\"_blank\" rel=\"noopener\">herdsman</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-04\">2026-11-04</time></td><td class=\"review-ref\"><a href=\"https://github.com/jirathip-dev/herdsman/tree/efd970e817c2021439c5415739e695f4af119b1d\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision efd970e817c2021439c5415739e695f4af119b1d\">efd970e &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: configured coding agent lanes implement and repair requested changes; separately tasked review agents exercise real task-specific judgment on code/tests. - Disturbance / variety regulated: new issue requirements, unknown codebase state, implementation errors, test failures and review findings. - Decisive decision or feedback right: choose which code and tests to change, what fixes to make and how to respond with evidence to reviewer findings within the owner-authorized issue. - Decision owner: model-based implementer and, for their bounded verification output, reviewer roles launched under the fleet pipeline; the deterministic drive merely chooses when to launch the next stage. - Supporting / enforcement mechanisms: herdr worktree/pane spawn, issue brief, role prompts, profile hooks, PR cache, head-pinned verdicts and event log. - Closure path: issue queued → implementer writes/tests/pushes change → reviewer evaluates exact head → FAIL returns findings to fix lane or PASS and green CI lead through merge gate → code reaches integration branch. - Boundary reachability: drive and timers launch the roles by supported fleet settings, and the named default pipeline wires their outputs back to future steps; this is not a unit-test-only role. - Why this is / is not agent-owned: code edits, targeted tests and adversarial judgments require meaningful agent choices; herdsman&#39;s hard transition and merge checks are constructor enforcement, not additional autonomous S1 judgment. - Evidence: role instructions, spawn source, pipeline. - Basis: documented supported operation plus pinned role and spawn wiring. - Confidence: high for model role construction, bounded for outcomes without a provider-backed run in this review. - Caveats: no agent executes without an installed, authenticated external harness and herdr; no unattended intelligence is attributed to the Rust scheduler itself.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S2 / coordination: - State: C - Function: first-party conflict preview, serial integration gate and isolated lane worktrees attenuate specific interference among concurrently coding issue units. - Disturbance / variety regulated: two issue agents editing overlapping files or branches cause rejected merges, overwrite/ordering hazards and repeated updates against the integration branch. - Decisive decision or feedback right: detect file-level collisions with git merge-tree, show the specific conflicting paths, order ready PRs, enforce required serial groups and return the losing lane to update its branch before another reviewed merge. - Decision owner: first-party deterministic overlap, drive, gate and serial-group rules; no model has a standing right to settle portfolio-wide branch conflicts by changing these policies. - Supporting / enforcement mechanisms: isolated worktrees, cached head-pair collision preview, HEADS-UP prompts, exact-head verdicts, serial gate and update rounds with bounded retry. - Closure path: conflicting concurrent heads → warning/serial ordering and first merge → implementer of later head receives update instruction and incorporates integration → fresh reviewer verdict and CI → next eligible merge. - Boundary reachability: the installed drive calls overlap preview before action ordering, and the supported conflict/behind path actively spawns an update role. - Why this is / is not agent-owned: concrete cross-issue contention is treated, but collision detection and merge precedence are coded invariants, not an autonomous S2 decision owner; this is C. - Distinct S1 units: independently running implementer lanes for different issue worktrees in the same configured fleet. - Inter-S1 disturbance: overlapping file edits and stale branch ancestry can make otherwise valid S1 output conflict at integration. - Attenuating coordination relation: file-level preview and first-ready ordering, strict serial marking, integration update and mandatory fresh review. - Feedback into subsequent S1 behaviour: later implementer gets exact conflicting paths/updated integration instructions, edits its work and pushes a changed head for another review. - Why this is S2-specific rather than generic communication / routing / sequencing / shared state / delegation: the relation recognizes actual write-set/merge interference between independent S1 agents and closes that conflict through a change in what the later agent does. - Evidence: overlap source, drive conflicts and ordering, lane conflict/update contract. - Basis: directly implemented collision-specific runtime path and prompt feedback. - Confidence: high for structural conflict attenuation; no claim of perfect prediction or autonomous negotiation. - Caveats: an early heads-up is advisory and does not lock all overlapping files; a first reviewed merge may still force an update round.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-p\" title=\"S3 / regulation: - State: P - Function: the human fleet owner sees the live issue/lane/host portfolio and can pause or resume a fleet, intervene in blocked work and decide current resource and merge envelopes. - Disturbance / variety regulated: excessive concurrent lanes, host pressure, stalled fixes, owner questions and unwanted work on active issues. - Decisive decision or feedback right: use the phone board/CLI to pause or resume, move/park an issue, answer owner asks, extend review rounds or grant the narrow owner override without bypassing exact-head review and CI. - Decision owner: fleet owner/operator. drive computes the next mechanically valid transition, but does not set purpose/priorities as an AI metasystem. - Supporting / enforcement mechanisms: live status, board and need-you cards, logged pause/decision events, queue moves, host admission and owner-only intervention controls. - Closure path: operator inspects current state → changes fleet pause/queue/decision or permitted round limit → next drive/kick reads event state and changes or withholds operational lane work. - Boundary reachability: pause, resume, ask, answer and board actions are shipped CLI/server paths and drive reads the same event log, not aspirational UI only. - Why this is / is not agent-owned: the human selects priorities and discretionary intervention; programmed drive and resource thresholds do not upgrade to S3 A. - Whole-system current view: board shows queue, pipeline, lanes, host load, waiting and needs-you across a fleet. - Current-control decision scope: current issue order, which work waits or proceeds, review rounds, host/cost envelope and capacity within configured policy. - Evidence: owner board and drive behavior, live host control, pause/answer implementation. - Basis: explicit human command path and recorded return to scheduler. - Confidence: high for supported owner mode; model-directed supervisor not established. - Caveats: UI requires a running server/paired device; same control also exists through CLI.\">P</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:3\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3* / direct audit: - State: A - Function: independent, adversarial reviewer agents inspect implementation code and objective acceptance evidence outside the implementer&#39;s self-report. - Disturbance / variety regulated: plausible but incorrect implementation claims, tests proving only mocks, leaked secrets and unreviewed scope changes. - Decisive decision or feedback right: read the actual diff and criteria, independently rerun tests and return a head-specific PASS/FAIL with blocking findings that the implementer must address. - Decision owner: a separately launched read-only reviewer model in a distinct lane and role/profile; verdict and CI checks merely enforce validity and preserve its findings. - Supporting / enforcement mechanisms: dedicated reviewer worktree, read-only pre-tool hook, verdict.md with reviewed 40-hex head and tests checked, exact-head gate and fresh check-round spawn. - Closure path: implementation PR head → reviewer inspects raw code/tests/criteria independently → head-pinned verdict and findings → implementer fix or approved integration → new head invalidates prior verdict and is independently reviewed again. - Boundary reachability: default and custom pipelines include independent check stages, distinct from build, with verified role constraints and drive spawns on pushed heads. - Why this is / is not agent-owned: adversarial technical judgment belongs to a distinct model role that can reject claims, not a boolean test wrapper or the implementer&#39;s own confirmation. - Claim being audited: implementation actually meets issue acceptance criteria and tests/PR description prove it. - Ordinary reporting path: implementer diff, test report and PR claim. - Complementary access path: independent checkout/diff, direct tests and head evidence against the original issue brief. - Independence boundary: reviewer role is prohibited from writing code, commits, pushes and PR comments, uses its own lane and verifies the actual current head; the same external harness vendor may still provide both models. - Who acts on findings: the subsequent implementer fix lane; herdsman&#39;s event/gate machine blocks merge until fresh PASS and green CI. - Evidence: reviewer role, review stage isolation, verdict source. - Basis: mandatory shipped review workflow and access separation. - Confidence: high for implemented audit path; reviewer accuracy not measured here. - Caveats: separate role/worktree provides process and tool isolation, not external institutional independence; no live paid provider review was performed in this assessment.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no first-party prospective outside-environment interpretation and return into enduring fleet capability changes was established. - Disturbance / variety regulated: new coding models, repository ecosystems, infrastructure economics and future workloads might eventually require adaptation. - Decisive decision or feedback right: no internal future-environment option selection and promotion right evidenced; host choices and code paths are bounded to present work/load. - Decision owner: not established for a separate S4 loop; fleet configuration and infrastructure upgrade choices remain with humans. - Supporting / enforcement mechanisms: host-history sampling, cost ceiling, doctor, backlog, context prompts and issue queue. - Closure path: observed present host pressure can deny a lane or start a configured cloud overflow host, but no projected external future becomes a selected enduring fleet strategy returned to implementation. - Why this is / is not agent-owned: capacity observation is near-term S3/operational admission, and repository improvement by contributors is outside the installed fleet recursion. - Evidence: host placement and budget, architecture and scope. - Basis: bounded negative source review of shipped operating modes. - Confidence: medium-high for missing S4 closure in the reviewed modes. - Caveats: future model/host choice by the operator is possible but not credited as installed autonomous S4.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no first-party loop was established that brings an identity- or ultimate-policy-level issue to legitimate authority and returns the binding result to govern the fleet as a coherent organization. - Disturbance / variety regulated: changing the fleet&#39;s ultimate mission, reconciling external future adaptation with current obligations, or revising the constitutional distribution of authority could require such a loop. - Decisive decision or feedback right: the owner may edit fleet.toml and decide scoped owner asks, but no shipped identity-level agenda or decision-return path was evidenced beyond those task and administration actions. - Decision owner: not established for S5 at the declared fleet recursion; ultimate responsibility remains with the human owner outside the demonstrated herdsman function. - Supporting / enforcement mechanisms: owner/routine ask classifier, OWNERTOPIC refusal, no-default owner answer, protected branches, command hooks, limit settings and fleet configuration. - Closure path: owner decisions are returned to individual tasks and settings bind future runs, but there is no demonstrated loop from an organization-level identity dispute through deliberation to a revised ultimate charter applied by the fleet. - Boundary reachability: task-level owner asks and configuration commands are shipped; their existence is not by itself S5 closure. - Why this is / is not agent-owned: approval for secrets, cost or scope during a single implementation may be important safety governance without constituting identity/policy-level VSM S5. - Evidence: owner/routine decision contract, ask/answer code, fleet policy and gate. - Basis: bounded negative first-party review, distinguishing task authorization from ultimate-policy closure. - Confidence: medium-high for this scoped absence; an independently organized human governance layer is not ruled out. - Caveats: this does not deny that an operator can govern or change herdsman outside the built fleet workflow.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/2500cd237846b78303b459e41ab53d20a64b0f13/assessments/he/herdsman.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 2500cd237846b78303b459e41ab53d20a64b0f13\">2500cd2 &#8599;</a></td></tr>","<tr class=\"has-a-combo\" data-combo=\"2\" data-a=\"2\" data-c=\"1\" data-assessment-at=\"2026-11-05T17:39:48+03:00\"><th scope=\"row\"><a href=\"https://github.com/Beyon-Digital/control-plane\" target=\"_blank\" rel=\"noopener\">Beyon Control Plane</a><small>2026</small></th><td class=\"counts-cell\" data-sort-value=\"2\"><div class=\"vhi-counts\"><span class=\"vhi-count count-a\">A <b>2</b></span><span class=\"vhi-count count-c\">C <b>1</b></span></div></td><td class=\"review-date\"><time datetime=\"2026-11-05\">2026-11-05</time></td><td class=\"review-ref\"><a href=\"https://github.com/Beyon-Digital/control-plane/tree/9dbe4012bdf8b2d2ee333402912b408aadd35e6d\" target=\"_blank\" rel=\"noopener\" title=\"Open pinned source revision 9dbe4012bdf8b2d2ee333402912b408aadd35e6d\">9dbe401 &#8599;</a></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S1 / operation: - State: A - Function: provider coding agents work on repo tasks through native worker session and tool/result feedback. - Disturbance / variety regulated: unknown code, compilation failures, tool restrictions, interrupted provider processes and changing workspace state. - Decisive decision or feedback right: each configured provider agent chooses coding actions and follow-up responses in its provider session, limited by its own approval policy and worker exposure; the first-party worker accepts, persists and reports concrete execution events. - Decision owner: model-backed Codex/Claude/Kiro agent; external provider inference is a runtime dependency, while Beyon owns the adapter, execution and feedback boundary. - Supporting / enforcement mechanisms: provider stdio/sidecar adapters, scoped session creation, event stream, workspace tools, idempotency receipts, device authorization and abort. - Closure path: prompt is accepted by worker → provider agent works with permitted tools → worker persists events and file effects → operator/orchestrator reads outcome and can issue follow-up or cancellation. - Boundary reachability: README documents installed providers and worker start; orchestrator&#39;s concrete createsession and promptsession routes call authenticated v1/sessions endpoints. The provider must separately be installed/authenticated. - Why this is / is not agent-owned: the provider agent selects how to do coding work rather than simply replaying deterministic scripts; host safety and networking alone are not the autonomous decision. - Evidence: run and provider boundary, provider adapters, orchestrator session calls. - Basis: source and supported deployment documentation; no live provider inference run. - Confidence: high for reachability; real account/provider integration is not independently proven. - Caveats: the external agents&#39; internal organizational functions are not copied into first-party Beyon ownership.\">A</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S2 / coordination: - State: — - Function: no evidenced inter-S1 conflict-specific reciprocal attenuation loop between independently acting coding agents. - Disturbance / variety regulated: independent sessions could edit shared files or compete for worker resources, but the reviewed implementation does not show a first-party overlap analyzer and corrective return to the competing operational units. - Decisive decision or feedback right: the orchestrator&#39;s tool calls are sequential and worker policies bound sessions/concurrency; neither explicitly identifies contested S1 obligations and reconciles them with collision feedback. - Decision owner: no distinct inter-S1 coordination owner established; session limits are deterministic worker enforcement. - Supporting / enforcement mechanisms: sequential model calls, per-account isolation, role grants, session ownership, worker quotas, Git conditional saves and separate worktrees. - Closure path: requests are authenticated and serialized locally where required; a resource denial returns an error, not an evidenced negotiation/adjustment between multiple S1 agents. - Boundary reachability: concurrency and host/account controls are shipped but do not themselves prove inter-S1 regulatory coordination. - Why this is / is not agent-owned: having many sessions, a central orchestrator and an action cap is insufficient without identified actual collisions and a feedback relation specifically resolving those collisions. - Evidence: orchestrator tool loop, worker controls, workspace operations. - Basis: bounded first-party negative inspection. - Confidence: medium; a model might manually notice a conflict, but a reproducible supported collision workflow is not demonstrated. - Caveats: explicit separate worktrees reduce collision probability; they do not automatically constitute S2.\">—</abbr></td><td class=\"state-cell\"><span class=\"combo-lightning\" style=\"--gap:2\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 28\" preserveAspectRatio=\"none\"><polyline class=\"lightning-glow\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline><polyline class=\"lightning-bolt\" points=\"0,14 12,9 22,17 34,6 45,16 57,10 68,19 80,7 90,16 100,14\"></polyline></svg></span><abbr tabindex=\"0\" class=\"vhi-state state-a combo-a\" title=\"S3 / regulation: - State: A(P) - Function: a client-side main orchestrator can inspect the present portfolio of installed agents, active sessions, progress and host account capabilities, and direct current coding work. - Disturbance / variety regulated: tasks accepted but not completed, unavailable providers, failed/uncertain sessions, unexpected file effects, new user priorities and permission changes. - Decisive decision or feedback right: when management is enabled, the main model can select a provider, create sessions, prompt them and interrupt a live run after querying hostinfo, listsessions, sessionevents, workspacediff and other evidence. Human retains scope and approval rights. - Decision owner: separate model-backed first-party OrchestratorEngine for operational session-portfolio decisions; human owner supplies binding agent-management permission, host/account selection and provider/tool approvals. - Supporting / enforcement mechanisms: scoped API client, model tool catalog/dispatcher allowlist, per-turn 10-round/40-call budget, user toggle, persistent worker session events and host access checks. - Closure path: current host/session/workspace evidence → orchestrator chooses create/prompt/interrupt or wait/inspect → worker accepts/rejects → event states return to subsequent model judgment and user UI. - Boundary reachability: OrchestratorEngine.run calls configured model inference and OrchestratorTools.execute implements actual endpoints, available from the native Orchestrator screen; read-only mode removes management calls. - Why this is / is not agent-owned: current portfolio management is an explicit model decision layer distinct from a worker&#39;s deterministic dispatch; notation includes (P) because the user holds the management enablement and unapproved tool authority. - Whole-system current view: worker host/provider discovery, per-session states/events, files and Git state across the connected account. - Current-control decision scope: creation, follow-up prompting, interruption and current inspection; not identity policy, user consent overrides or provider permission approval. - Evidence: executable tool catalog and dispatch, orchestrator limits and scope. - Basis: first-party model loop and scoped live API wiring; not a successful real model-provider performance claim. - Confidence: medium-high for implemented mode, with uncertainty about account entitlement and real deployment operation. - Caveats: without a connected worker or with management disabled, this S3 agent&#39;s action right is absent; these modes are not silently credited with full orchestration.\">A(P)</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-c\" title=\"S3* / direct audit: - State: C - Function: provide evidence independent of coding-agent prose about actual session acceptance/completion, worker state and Git working-tree differences, enabling a corrective decision. - Disturbance / variety regulated: a coding agent can claim a task is done when a prompt was only accepted or its changes are missing; client state can be stale after disconnect/restart. - Decisive decision or feedback right: orchestrator/human can query durable worker sessionevents, listsessions and raw workspacediff, compare to the coding agent&#39;s story and then change follow-up or interrupt; the alternative evidence path itself is deterministic rather than a dedicated autonomous auditor. - Decision owner: independent first-party worker event/actual-file evidence constructor (C); model orchestrator or human interprets it, but the code does not guarantee a distinct adversarial auditing-model verdict. - Supporting / enforcement mechanisms: durable SQLite events and receipts, restart uncertain rather than success/replay, actual workspace Git diff endpoint, clear prompt acceptance semantics. - Closure path: provider report/accepted prompt → fresh worker events and raw Git diff challenge the claimed state → main orchestrator/user can send a correction or halt a session → next provider action and events reflect the adjustment. - Boundary reachability: model tool catalog includes these live read-only tools, backed by worker API and stored events; the docs explicitly instruct inspection rather than treating acceptance as completion. - Why this is / is not agent-owned: these observations do not originate in the coding agent&#39;s natural-language assertion, yet no separate reviewer model automatically produces a verdict; hence a complementary constructor, not S3 A. - Claim being audited: the provider agent actually completed requested work and current workspace effects match its claimed progress. - Ordinary reporting path: provider messages, prompt-accepted notifications and local client conversation state. - Complementary access path: persisted host event cursor/status and independent Git filesystem diff read through the authenticated worker. - Independence boundary: coding agents can change workspace files and might manipulate their own outputs; the event store is separately maintained by the worker, but does not prove correctness, and actual Git diff alone cannot validate tests. - Who acts on findings: parent human or client-side orchestrator issues a new prompt, pauses, or explicitly declines completion claims. - Evidence: orchestrator independent read tools, durable events and restart semantics, worker store. - Basis: first-party separate observation and optional corrective return, not an observed independent semantic audit. - Confidence: medium: robust source separation, discretionary rather than mandatory corrective use. - Caveats: an orchestrator can choose not to inspect, and a diff can miss semantics; no guaranteed code-review safety threshold is inferred.\">C</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S4 / adaptation: - State: — - Function: no packaged externally prospective scenario/option selection feeding durable changes to future operating capabilities. - Disturbance / variety regulated: future agent/provider availability, model eligibility, host topology and longer-term developer workflows may shift. - Decisive decision or feedback right: humans select current model profiles/endpoints, connect hosts and install workers; model discovery and account authorization are present-day capability choices, not a strategic outside-and-then return loop. - Decision owner: developer/operator configuration; no distinct first-party S4 intelligence decision owner. - Supporting / enforcement mechanisms: model profiles and discovery, platform release/updater, host management, installation and verification guides. - Closure path: a user can switch a model or host and run the current orchestrator, but there is no shown future environment options assessment that binds a changed long-term operating capability through S3. - Why this is / is not agent-owned: discovering current models and installing signed updates are not VSM S4 merely because they concern technological change. - Evidence: model setup, architecture and update trust. - Basis: bounded negative review of shipped model/settings, current orchestrator and future release modes. - Confidence: medium-high at declared host/account recursion. - Caveats: developer roadmap and update mechanisms can evolve without proving a deployed prospective adaptation regulator.\">—</abbr></td><td class=\"state-cell\"><abbr tabindex=\"0\" class=\"vhi-state state-none\" title=\"S5 / identity: - State: — - Function: no evidenced ultimate identity/purpose policy conflict adjudicated by a legitimate organizational authority and returned to runtime commitments. - Disturbance / variety regulated: conflicting device trust, human permission and long-term assistant identity may require parent policy, but runtime currently applies already configured controls. - Decisive decision or feedback right: administrators enroll/revoke devices and grant roles; the user enables agent management, accepts provider permissions and can emergency-stop. These are scoped operational/security rights, not identity-policy adjudication. - Decision owner: outside human user/account administrator and project governance; no shipped distinct S5 decision loop with a charter-level return. - Supporting / enforcement mechanisms: TLS device identity, role/session ACL, certificate renewal, worker privilege boundaries, explicit trusted mode and emergency stop. - Closure path: permission changes apply to future API calls and revoke streams, without a witnessed foundational identity dispute being raised, decided and returned as ultimate policy across the organization. - Why this is / is not agent-owned: revocation and human override are genuine safeguards but not sufficient S5 closure; no autonomous S5 is inferred from a secure product name or operator veto. - Evidence: trust model and deployment limits, human agent-management bounds. - Basis: bounded negative inspection of actual governance/permissions rather than contributor organization. - Confidence: medium-high. - Caveats: multi-user administrators can govern security policies, but that is not an evidenced question-to-legitimate-S5-to-binding-operational-return loop at this boundary.\">—</abbr></td><td class=\"assessment-ref\"><a href=\"https://github.com/opensiro/vsm-harness-index/blob/8ba36072b4c05023dce5352227d9a0bad1958d31/assessments/be/beyon-control-plane.md\" target=\"_blank\" rel=\"noopener\" title=\"Open assessment at commit 8ba36072b4c05023dce5352227d9a0bad1958d31\">8ba3607 &#8599;</a></td></tr>"];
